import Foundation

/// The control API described as an OpenAPI 3.1 document, **derived from
/// `ControlRouter.table`** rather than written alongside it. Served at
/// `GET /v1/openapi.json`.
///
/// The table is the only place that knows which endpoints exist, so the paths of
/// this document are generated by walking `ControlRouter.endpoints`: method, path
/// and auth requirement can't drift from the router, because they *are* the
/// router. What the table doesn't carry — what a request body holds, what comes
/// back — is the `detail(for:)` switch below, which is exhaustive over
/// `ControlRoute`: a new case fails to compile until it is described, and
/// `ControlAPISpecTests` fails if a row ever reaches the document without one.
///
/// Everything here is checked against `KiteloopControlServer`'s handlers by hand.
/// A schema the handler doesn't actually return would be worse than no schema at
/// all — it would be believed — so where a response varies (the keys a run status
/// carries depend on how far the run got), only the keys the handler emits
/// unconditionally are `required` and the conditional ones are listed as optional.
///
/// Deliberately free of app types (only Foundation), so the document can be
/// generated — and validated — without standing up the app.
package enum ControlAPISpec {

    package static let openAPIVersion = "3.1.0"

    /// `version` is the app's `CFBundleShortVersionString` and `port` the port the
    /// server is actually listening on, so `servers[0].url` is a URL the caller
    /// that fetched this document can use as-is.
    package static func document(version: String, port: UInt16) -> [String: Any] {
        [
            "openapi": openAPIVersion,
            "info": [
                "title": "Kiteloop control API",
                "version": version,
                "summary": "Drive Kiteloop headlessly: open a project, configure autopilot, run a backlog item and approve the result.",
                "description": """
                A loopback-only HTTP API served by the Kiteloop app on 127.0.0.1. Off by \
                default — enable it in Settings → General → Local Control API.

                This document is generated from the app's routing table, so its paths, \
                methods and auth requirements are exactly the ones the running build \
                answers. Request and response schemas are maintained against the handlers \
                by hand: where a response body varies with run state, only the \
                unconditional keys are marked required.

                Not modelled here: 413 (a request body over 2 MB) and 500 (an unhandled \
                failure), which the transport can return for any route; and the query \
                string `project` accepting a canonical path, a raw path or a bare folder \
                name. See docs/control-api.md for the prose reference.
                """
            ],
            "servers": [["url": "http://127.0.0.1:\(port)", "description": "The app on this machine"]],
            // Applied to every operation; `/health` opts out with an empty
            // requirement, which is the only place the table says auth isn't needed.
            "security": [["bearerAuth": [String]()]],
            "components": [
                "securitySchemes": [
                    "bearerAuth": [
                        "type": "http",
                        "scheme": "bearer",
                        "description": "The token at ~/.kiteloop/control-token, compared as an exact full string."
                    ]
                ],
                "schemas": schemas
            ],
            "paths": paths()
        ]
    }

    /// The document as the bytes the endpoint serves: sorted keys and pretty
    /// printing, matching every other control-API response.
    package static func json(version: String, port: UInt16) throws -> Data {
        try JSONSerialization.data(withJSONObject: document(version: version, port: port),
                                   options: [.sortedKeys, .prettyPrinted])
    }

    // MARK: - Paths, walked from the routing table

    private static func paths() -> [String: Any] {
        var paths: [String: [String: Any]] = [:]
        for endpoint in ControlRouter.endpoints {
            var item = paths[endpoint.templatedPath] ?? [:]
            if !endpoint.pathParameters.isEmpty {
                item["parameters"] = endpoint.pathParameters.map { name in
                    [
                        "name": name,
                        "in": "path",
                        "required": true,
                        "schema": string,
                        "description": pathParameterDescriptions[name] ?? "Path parameter."
                    ] as [String: Any]
                }
            }
            item[endpoint.method.lowercased()] = operation(for: endpoint)
            paths[endpoint.templatedPath] = item
        }
        return paths
    }

    private static func operation(for endpoint: ControlRouter.Endpoint) -> [String: Any] {
        let detail = self.detail(for: endpoint.route)
        var operation: [String: Any] = [
            "operationId": detail.id,
            "summary": detail.summary,
            "responses": responses(detail, requiresAuth: endpoint.requiresAuth)
        ]
        if let description = detail.description { operation["description"] = description }
        if !detail.query.isEmpty {
            operation["parameters"] = detail.query.map(\.json)
        }
        if let body = detail.requestBody {
            operation["requestBody"] = [
                "required": detail.requestBodyRequired,
                "content": ["application/json": ["schema": body]]
            ] as [String: Any]
        }
        // The one unauthenticated route drops the document-wide requirement. This
        // comes from the route, not from a list kept here, so it stays true if the
        // policy on a route ever changes.
        if !endpoint.requiresAuth { operation["security"] = [[String: [String]]]() }
        return operation
    }

    private static func responses(_ detail: Detail, requiresAuth: Bool) -> [String: Any] {
        var responses: [String: Any] = [:]
        for status in detail.responses {
            var response: [String: Any] = ["description": status.description]
            if let schema = status.schema {
                response["content"] = [status.contentType: ["schema": schema]]
            }
            responses["\(status.code)"] = response
        }
        // Every authenticated route answers 401 the same way, so it's derived here
        // rather than repeated thirty times below.
        if requiresAuth {
            responses["401"] = errorResponse("Missing or invalid bearer token.")
        }
        return responses
    }

    // MARK: - What each route accepts and returns

    private struct Detail {
        let id: String
        let summary: String
        var description: String?
        var query: [QueryParameter] = []
        var requestBody: [String: Any]?
        var requestBodyRequired = true
        var responses: [Status]
    }

    private struct QueryParameter {
        let name: String
        let required: Bool
        let schema: [String: Any]
        let description: String

        var json: [String: Any] {
            ["name": name, "in": "query", "required": required, "schema": schema, "description": description]
        }
    }

    private struct Status {
        let code: Int
        let description: String
        var schema: [String: Any]?
        var contentType = "application/json"
    }

    // MARK: - What each route accepts and returns, by family

    /// Exhaustive over `ControlRoute` on purpose: adding a route without saying
    /// what it does is a compile error, not a silently thin document. What each
    /// route says is one function of its own, reached through the family it
    /// belongs to — so a route's description changes without touching any other's,
    /// and this switch changes only when a family gains or loses a member.
    private static func detail(for route: ControlRoute) -> Detail {
        switch route {
        case .health, .openAPIDocument, .claimPairingCode, .listQuickReplies,
             .registerPushDevice, .registerLiveActivity:
            return metaDetail(for: route)
        case .listProjects, .openProject, .reorderProjects, .askAboutProject,
             .workspaceChanges, .workspaceFile, .previewScreenshot,
             .hireAgent, .listAgents, .messageAgent, .agentTranscript, .agentEvents,
             .interruptAgent, .answerAgentPlan, .answerAgentQuestion,
             .listMemoryProposals, .approveMemoryProposal, .rejectMemoryProposal:
            return teamDetail(for: route)
        case .listBacklog, .backlogItemDetail, .backlogItemDiff,
             .approveBacklogItem, .landBacklogItem, .moveBacklogItem, .setBacklogItemLane, .groomBacklogItem,
             .releaseBacklogItem, .refreshBacklogItem,
             .listTemplates, .stampTemplate, .fileBacklogItem,
             .listMetrics, .listEstimates, .listGrooming, .portfolioReport:
            return backlogDetail(for: route)
        case .getAutopilot, .setAutopilot, .resetAutopilot, .pauseAutopilot, .resumeAutopilot,
             .fleetStatus, .quiesceFleet, .resumeFleet, .usage:
            return queueDetail(for: route)
        case .getCoordinatorRefill, .setCoordinatorRefill,
             .getCoordinatorScheduling, .setCoordinatorScheduling,
             .listProposals, .approveProposal, .dismissProposal:
            return coordinatorDetail(for: route)
        case .startRun, .approveRun, .cancelRun, .steerRun,
             .listRuns, .runStatus, .runResult, .runEvents, .runLog:
            return runDetail(for: route)
        }
    }

    // MARK: - Meta: the liveness probe and this document

    /// The two routes that describe the app rather than its work.
    private static func metaDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .health: return healthDetail()
        case .openAPIDocument: return openAPIDocumentDetail()
        case .claimPairingCode: return claimPairingCodeDetail()
        case .listQuickReplies: return listQuickRepliesDetail()
        case .registerPushDevice: return registerPushDeviceDetail()
        case .registerLiveActivity: return registerLiveActivityDetail()
        default:
            preconditionFailure("\(route) is not a meta route")
        }
    }

    private static func listQuickRepliesDetail() -> Detail {
        return Detail(
            id: "listQuickReplies",
            summary: "The one-tap replies the phone offers in a chat",
            description: """
            The replies kept under Settings → Control API → Quick replies, which \
            the phone shows as chips above its chat composer. Until the list is \
            set it is three starters; a list cleared in Settings stays empty.
            """,
            responses: [
                Status(code: 200, description: "The list, in order.", schema: object([
                    "replies": described(array(of: string), "Each reply as it is sent.")
                ], required: ["replies"]))
            ]
        )
    }

    private static func claimPairingCodeDetail() -> Detail {
        return Detail(
            id: "claimPairingCode",
            summary: "Trade a pairing code for a phone's own token",
            description: """
            The one-time code the Mac's pairing QR carries, traded for a token of             the phone's own. A code pairs one phone once, and only while the Mac's             pairing sheet that shows it is open: a claimed code, one whose sheet was             closed and one from before a relaunch are all refused. Needs no bearer             token — the code stands in for it.
            """,
            requestBody: object([
                "code": described(string, "The code from the pairing QR."),
                "name": described(string, "What Settings lists the phone as.")
            ], required: ["code"]),
            responses: [
                Status(code: 200, description: "Paired.", schema: object([
                    "token": described(string, "The phone's own bearer token."),
                    "device": described(string, "The paired phone's id, as Settings lists it.")
                ], required: ["token", "device"])),
                errorStatus(400, "No code."),
                errorStatus(403, "The code is not on offer: used, withdrawn, or never shown."),
                errorStatus(404, "This Mac keeps no paired phones.")
            ]
        )
    }

    private static func registerLiveActivityDetail() -> Detail {
        return Detail(
            id: "registerLiveActivity",
            summary: "Register a Live Activity for an agent's turn",
            description: """
            The push token of the Live Activity a phone started when it sent an agent \
            a message. The Mac moves it on with live-activity pushes — waiting for your \
            answer, a plan ready, then done — so the lock screen follows the turn while \
            the phone sleeps. Held for that one turn, in memory.
            """,
            requestBody: object([
                "token": described(string, "The activity's push token, hex."),
                "environment": described(string, "sandbox or production."),
                "project": described(string, "The project name, as GET /v1/projects gives it."),
                "agent": described(string, "The agent's id.")
            ], required: ["token", "environment", "project", "agent"]),
            responses: [
                Status(code: 200, description: "Registered.", schema: object(["registered": bool], required: ["registered"])),
                errorStatus(400, "A missing field, a non-hex token or an unknown environment.")
            ]
        )
    }

    private static func registerPushDeviceDetail() -> Detail {
        return Detail(
            id: "registerPushDevice",
            summary: "Register a phone for push notifications",
            description: """
            The phone's APNs device token, and which push service it belongs to: \
            `sandbox` for a build run from Xcode, `production` for TestFlight. The \
            Mac then pushes when an item reaches the approval gate, an agent asks \
            something or has a plan ready, a background project finishes, or a turn \
            started from the phone ends. Registering the same token again replaces \
            it. `problem` says why nothing will arrive yet — no push key in Settings.
            """,
            requestBody: object([
                "token": described(string, "The APNs device token, hex."),
                "environment": described(string, "sandbox or production."),
                "name": described(string, "What Settings lists the phone as.")
            ], required: ["token", "environment"]),
            responses: [
                Status(code: 200, description: "Registered.", schema: object([
                    "registered": bool,
                    "problem": described(string, "Why pushes will not arrive yet, when they will not.")
                ], required: ["registered"])),
                errorStatus(400, "A missing or non-hex token, or an unknown environment."),
                errorStatus(503, "Pushes are not set up on this Mac.")
            ]
        )
    }

    private static func healthDetail() -> Detail {
        return Detail(
            id: "getHealth",
            summary: "Liveness probe",
            description: """
            The one unauthenticated route. `uptimeSeconds` is how a long-lived driver \
            detects a restart: run records live in memory, so an uptime that went down \
            means every runId it holds is now a 404. `status` reads "degraded" — rather \
            than the "ok" a busy app would also answer — when mainThreadLatencyMs is at \
            or above the app's own hitch threshold (200ms), so a wedged app reads \
            differently from one merely working. `tools` is, per open project, every executable its verify commands run and where the app's search path resolved it — or null with the directories searched — before a run is refused for it; beside them, `exports` is what every verify and agent spawn on the project's behalf runs with beyond PATH: the build output shared across its item worktrees.
            """,
            responses: [Status(code: 200, description: "The app is up.", schema: ref("Health"))]
        )
    }

    private static func openAPIDocumentDetail() -> Detail {
        return Detail(
            id: "getOpenAPIDocument",
            summary: "This document",
            description: """
            The control API as OpenAPI 3.1, generated from the running build's routing \
            table — so it describes the endpoints this app actually answers, not the \
            ones a checked-in file was last regenerated against.
            """,
            responses: [
                Status(code: 200, description: "The OpenAPI document.",
                       schema: described(["type": "object"], "An OpenAPI 3.1 document."))
            ]
        )
    }

    // MARK: - Team: a project, the agents in it and their memory

    /// The project, the agents hired into it and the memory they propose —
    /// one arm per family, each family a switch of its own.
    private static func teamDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .listProjects, .openProject, .reorderProjects, .askAboutProject,
             .workspaceChanges, .workspaceFile, .previewScreenshot: return projectDetail(for: route)
        case .hireAgent, .listAgents, .messageAgent, .agentTranscript, .agentEvents: return agentDetail(for: route)
        case .interruptAgent, .answerAgentPlan, .answerAgentQuestion: return agentSteeringDetail(for: route)
        case .listMemoryProposals, .approveMemoryProposal, .rejectMemoryProposal: return memoryDetail(for: route)
        default:
            preconditionFailure("\(route) is not a team route")
        }
    }

    /// The `/v1/projects…` family — the project tabs themselves, and the one
    /// route that reads a project's source.
    private static func projectDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .listProjects: return listProjectsDetail()
        case .openProject: return openProjectDetail()
        case .reorderProjects: return reorderProjectsDetail()
        case .askAboutProject: return askAboutProjectDetail()
        case .workspaceChanges, .workspaceFile, .previewScreenshot: return workspaceDetail(for: route)
        default:
            preconditionFailure("\(route) is not a project route")
        }
    }

    /// The project's working tree and web preview, read from a phone.
    private static func workspaceDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .workspaceChanges: return workspaceChangesDetail()
        case .workspaceFile: return workspaceFileDetail()
        default: return previewScreenshotDetail()
        }
    }

    private static func workspaceChangesDetail() -> Detail {
        return Detail(
            id: "workspaceChanges",
            summary: "The project's uncommitted changes",
            description: """
            What an agent has changed so far, before anything reaches a gate: every \
            changed or untracked file with its `git status` letters, and the patch \
            against HEAD for the tracked ones, cut at 200,000 characters — \
            `truncated` says when.
            """,
            query: [projectQuery(required: true)],
            responses: [
                Status(code: 200, description: "The changes; an empty list for a clean tree.", schema: object([
                    "files": array(of: object(["status": string, "path": string], required: ["status", "path"])),
                    "patch": string, "truncated": bool
                ], required: ["files", "patch", "truncated"])),
                errorStatus(400, "Missing ?project=."),
                errorStatus(409, "Project not open, or not a git repository."),
                errorStatus(504, "git did not answer in time.")
            ])
    }

    private static func workspaceFileDetail() -> Detail {
        return Detail(
            id: "workspaceFile",
            summary: "One file or folder of the project, read-only",
            description: """
            `path` is relative to the project. A file answers its text, a folder its \
            entries. Refused: a path that leaves the project (`..` or a symlink), \
            `.git`, and anything git ignores — where env files and keys live.
            """,
            query: [projectQuery(required: true),
                    QueryParameter(name: "path", required: false, schema: string,
                                   description: "Relative to the project, or absolute inside it; empty for its root.")],
            responses: [
                Status(code: 200, description: "The file or folder.", schema: object([
                    "path": string, "kind": described(string, "file or directory."),
                    "text": string,
                    "entries": array(of: object(["name": string, "directory": bool], required: ["name", "directory"]))
                ], required: ["path", "kind"])),
                errorStatus(400, "Missing ?project=."),
                errorStatus(403, "Outside the project, inside .git, or ignored by git."),
                errorStatus(404, "No such file."),
                errorStatus(409, "Project not open."),
                errorStatus(413, "A file over 500,000 bytes."),
                errorStatus(415, "Not text.")
            ])
    }

    private static func previewScreenshotDetail() -> Detail {
        return Detail(
            id: "previewScreenshot",
            summary: "The web preview, as a PNG",
            description: "What the Mac's web preview pane shows for this project, so UI work can be checked from a phone.",
            query: [projectQuery(required: true)],
            responses: [
                Status(code: 200, description: "The preview.", schema: described(string, "PNG bytes."),
                       contentType: "image/png"),
                errorStatus(400, "Missing ?project=."),
                errorStatus(409, "Project not open, or no web preview open for it.")
            ])
    }

    private static func listProjectsDetail() -> Detail {
        return Detail(
            id: "listProjects",
            summary: "List the projects open in the app",
            description: """
            Each project carries its autopilot run state and its queue depth, so \
            "what is every project doing, and what has it left to do?" is one call \
            rather than one GET /v1/autopilot and one GET /v1/backlog per project.
            """,
            responses: [Status(code: 200, description: "Open projects.", schema: ref("ProjectList"))]
        )
    }

    private static func openProjectDetail() -> Detail {
        return Detail(
            id: "openProject",
            summary: "Open a project in the app",
            description: "201 when a session was created; 200 when the project was already open and has been re-read from disk.",
            requestBody: object(["path": described(string, "Filesystem path to the project root. A leading ~ is expanded.")],
                                required: ["path"]),
            responses: [
                Status(code: 200, description: "Already open — reloaded from disk.", schema: ref("OpenedProject")),
                Status(code: 201, description: "Opened.", schema: ref("OpenedProject")),
                errorStatus(400, "Body wasn't `{ \"path\": … }`, or no project could be opened there."),
                errorStatus(503, "The app window isn't running, so nothing can open a project.")
            ]
        )
    }

    private static func reorderProjectsDetail() -> Detail {
        return Detail(
            id: "reorderProjects",
            summary: "Move an open project's tab before another, or to the end",
            description: """
            The same move a tab drop makes in the app window, so the phone and the Mac \
            share one order. `GET /v1/projects` lists projects in that order. Answers the \
            new order as project names.
            """,
            requestBody: object([
                "project": described(string, "The project to move — its name or its path."),
                "before": described(string, "The project to place it in front of — name or path. Omit or null to move it to the end.")
            ], required: ["project"]),
            responses: [
                Status(code: 200, description: "Moved.", schema: object(["projects": described(array(of: string), "Project names in the new tab order.")], required: ["projects"])),
                errorStatus(400, "Body wasn't `{ \"project\": … }`."),
                errorStatus(409, "`project` or `before` names no open project."),
                errorStatus(503, "The app window isn't running, so there is no tab order to move.")
            ]
        )
    }

    private static func askAboutProjectDetail() -> Detail {
        return Detail(
            id: "askAboutProject",
            summary: "Ask the Planner about one project's source",
            description: """
            Answers a question about a named project's **source**, read-only — for what \
            the backlog genuinely cannot answer: whether a file is still there, whether a \
            symbol exists, what a test actually asserts. Everything the app already holds \
            is cheaper and stays the default: `GET /v1/backlog`, `/v1/runs` and \
            `/v1/report` cost nothing and answer most questions about a project. This one \
            spends a model call with tools, so expect a materially higher per-call cost.

            Scoped to the one project named, resolved against the open projects by their \
            own name or path — a name that matches nothing answers 404 listing the open \
            ones, rather than the nearest project. The reading agent is granted `Glob`, \
            `Grep` and `Read` and nothing else: it cannot write a file, run a command or \
            reach the network, and it cannot read another project. Asked about something \
            it did not read, it says so rather than answering from the backlog.

            Charged to the portfolio's daily ceiling, the same pool grooming draws on; an \
            exhausted ceiling answers 429 and spends nothing. The answer is capped, and a \
            capped one says so — in `capped` and in the text of `answer` itself.
            """,
            requestBody: object([
                "project": described(string, "Project identifier — canonical path, raw path or folder name."),
                "question": described(string, "What to find out. Must not be empty."),
                "q": described(string, "Accepted as an alias for \"question\".")
            ], required: ["project"], anyOfRequired: [["question"], ["q"]]),
            responses: [
                Status(code: 200, description: "Answered.", schema: ref("ProjectAnswer")),
                errorStatus(400, "Body is missing \"project\", or \"question\" is absent or empty."),
                errorStatus(404, "No open project by that name — the open ones are listed in the message."),
                errorStatus(429, "The portfolio's daily ceiling is spent; nothing was read."),
                errorStatus(502, "The read happened and came back empty."),
                errorStatus(503, "No Planner is attached to this window to do the reading.")
            ]
        )
    }

    /// The `/v1/agents…` family, plus hiring one into a project.
    private static func agentDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .hireAgent: return hireAgentDetail()
        case .listAgents: return listAgentsDetail()
        case .messageAgent: return messageAgentDetail()
        case .agentTranscript: return agentTranscriptDetail()
        case .agentEvents: return agentEventsDetail()
        default:
            preconditionFailure("\(route) is not an agent route")
        }
    }

    /// Steering an agent mid-conversation.
    private static func agentSteeringDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .interruptAgent: return interruptAgentDetail()
        case .answerAgentPlan: return answerAgentPlanDetail()
        case .answerAgentQuestion: return answerAgentQuestionDetail()
        default:
            preconditionFailure("\(route) is not an agent steering route")
        }
    }

    private static func hireAgentDetail() -> Detail {
        return Detail(
            id: "hireAgent",
            summary: "Hire an agent into a project",
            requestBody: object([
                "project": described(string, "Project identifier — canonical path, raw path or folder name."),
                "name": described(string, "Display name for the agent. Must not be empty."),
                "model": described(string, "Model id. Defaults to the catalog's default model."),
                "permissionMode": described(string, "Defaults to the project's configured mode, \"auto\" unless set."),
                "systemPrompt": string,
                "avatar": string,
                "tools": array(of: string),
                "select": described(bool, "Select the new agent in the UI. Defaults to false so a headless call doesn't steal the user's view.")
            ], required: ["project", "name"]),
            responses: [
                Status(code: 201, description: "Hired.", schema: ref("HiredAgent")),
                errorStatus(400, "Body is missing \"project\" or a non-empty \"name\"."),
                errorStatus(409, "Project not open in Kiteloop.")
            ]
        )
    }

    private static func listAgentsDetail() -> Detail {
        return Detail(
            id: "listAgents",
            summary: "List a project's agents",
            description: """
            Every agent hired into the project — id, name, model and state \
            (`idle`, `working`, `waitingForHuman`). The id is what the message \
            and transcript endpoints take, though both accept the name too.
            """,
            query: [projectQuery(required: true)],
            responses: [
                Status(code: 200, description: "The project's agents.", schema: ref("AgentList")),
                errorStatus(400, "Missing ?project=."),
                errorStatus(409, "Project not open in Kiteloop.")
            ]
        )
    }

    private static func messageAgentDetail() -> Detail {
        return Detail(
            id: "messageAgent",
            summary: "Send a message to an agent",
            description: """
            Delivers the message into the agent's chat session exactly as if \
            typed there — same transcript, same tool handling — and answers as \
            soon as it is in: `started` when the agent was idle, `queued` when it \
            was mid-turn and the message waits its turn. `after` is the id of the \
            chat's last message before this one; open `GET /v1/agents/events` \
            with it to follow the reply as it streams. With `"wait": true` the \
            call instead answers when the agent finishes its turn, with the reply \
            text — or `queued` at once, as before.
            """,
            requestBody: agentMessageBody,
            responses: [
                Status(code: 200, description: "The agent's reply, or queued.", schema: ref("AgentMessage")),
                errorStatus(400, "Body is missing \"project\" or \"agent\", or has neither a message nor an image."),
                errorStatus(404, "No such agent in this project."),
                errorStatus(409, "Project not open in Kiteloop."),
                errorStatus(413, "An image over the 5 MB a model takes, or a body over 2 MB."),
                errorStatus(415, "An attachment that is not a PNG, JPEG, GIF or WebP image.")
            ]
        )
    }

    private static func agentEventsDetail() -> Detail {
        return Detail(
            id: "streamAgentEvents",
            summary: "An agent's chat as it happens (SSE)",
            description: """
            Each frame's data is one JSON object. `{"type": "message", "agent", \
            "message"}` carries a transcript message — the same shape the \
            transcript endpoint answers — each time it is new or changes, so a \
            reply still streaming arrives again and again under one id: replace \
            by id. `{"type": "state", "agent", "working"}` says the agent started \
            or finished a turn, and goes out first on every connection. With \
            `after`, every message after that one is sent at once; an id the chat \
            does not hold sends the whole window again. Without it the stream \
            starts from now. The stream watches the newest `limit` messages, \
            default 50, the same window a transcript read answers. A \
            `: keepalive` comment goes out every 15s.
            """,
            query: [projectQuery(required: true),
                    QueryParameter(name: "agent", required: true, schema: string, description: "Agent id or name."),
                    QueryParameter(name: "after", required: false, schema: string,
                                   description: "The last message id the client holds."),
                    QueryParameter(name: "limit", required: false, schema: integer, description: "Newest messages watched; default 50.")],
            responses: [
                Status(code: 200,
                       description: "An SSE stream of message and state events.",
                       schema: described(string, "SSE frames, newline-delimited."),
                       contentType: "text/event-stream"),
                errorStatus(400, "Missing ?project= or ?agent=."),
                errorStatus(404, "No such agent in this project."),
                errorStatus(409, "Project not open in Kiteloop.")
            ]
        )
    }

    private static func interruptAgentDetail() -> Detail {
        return Detail(
            id: "interruptAgent",
            summary: "Stop an agent's running turn",
            description: """
            What the Mac's Stop button does: the turn ends, and messages you queued \
            during it go back into the Mac's input box. `returned` carries their \
            text so a phone can put it in its own draft. An agent with no turn \
            running answers `interrupted: false` and nothing changes.
            """,
            requestBody: agentTargetBody([:], required: []),
            responses: [
                Status(code: 200, description: "Whether a turn was stopped.", schema: object([
                    "agent": string,
                    "interrupted": bool,
                    "returned": described(string, "The queued messages, joined by blank lines; present when interrupted.")
                ], required: ["agent", "interrupted"])),
                errorStatus(400, "Body is missing \"project\" or \"agent\"."),
                errorStatus(404, "No such agent in this project."),
                errorStatus(409, "Project not open in Kiteloop.")
            ]
        )
    }

    private static func answerAgentPlanDetail() -> Detail {
        return Detail(
            id: "answerAgentPlan",
            summary: "Answer a Plan-mode agent's plan card",
            description: """
            The plan card's three buttons. `approveAuto` and `approveAcceptEdits` \
            switch the agent to that mode and tell it to build; `keepPlanning` \
            leaves it planning and sends `feedback`, if any, as your message. \
            Answered as soon as the card is: the build turn shows on the events stream.
            """,
            requestBody: agentTargetBody([
                "message": described(string, "The plan message's id, as the transcript gives it."),
                "answer": described(string, "approveAuto, approveAcceptEdits or keepPlanning."),
                "feedback": described(string, "With keepPlanning: what should change.")
            ], required: ["message", "answer"]),
            responses: [
                Status(code: 200, description: "The card is answered.", schema: object([
                    "agent": string, "message": string, "answer": string
                ], required: ["agent", "message", "answer"])),
                errorStatus(400, "A missing field, or an answer that is not one of the three."),
                errorStatus(404, "No such agent in this project."),
                errorStatus(409, "Project not open, or no open plan with that id — answered already, or not a plan.")
            ]
        )
    }

    private static func answerAgentQuestionDetail() -> Detail {
        return Detail(
            id: "answerAgentQuestion",
            summary: "Answer the question an agent stopped to ask",
            description: """
            An agent's `ask_human` question pauses its turn until answered. This \
            answers it — only the one the agent is waiting on now — and the turn \
            resumes; the reply shows on the events stream.
            """,
            requestBody: agentTargetBody([
                "request": described(string, "The question's request id, as the transcript gives it."),
                "answer": described(string, "Your answer. Must not be blank.")
            ], required: ["request", "answer"]),
            responses: [
                Status(code: 200, description: "Answered; the turn resumes.", schema: object([
                    "agent": string, "request": string
                ], required: ["agent", "request"])),
                errorStatus(400, "Body is missing a field, or the answer is blank."),
                errorStatus(404, "No such agent in this project."),
                errorStatus(409, "Project not open, or the agent is not waiting on that question.")
            ]
        )
    }

    /// A body naming a project and an agent, plus `extra`.
    private static func agentTargetBody(_ extra: [String: Any], required: [String]) -> [String: Any] {
        var properties: [String: Any] = [
            "project": described(string, "Project identifier."),
            "agent": described(string, "Agent id or name.")
        ]
        properties.merge(extra) { _, new in new }
        return object(properties, required: ["project", "agent"] + required)
    }

    private static func agentTranscriptDetail() -> Detail {
        return Detail(
            id: "agentTranscript",
            summary: "An agent's recent chat transcript, oldest first",
            description: """
            The conversation as the Mac shows it, flattened to what a phone can \
            render: sender, kind (`text`, `thinking`, `tool`, `error`, `system`) \
            and text. `limit` caps how many of the newest messages come back \
            (default 50). An agent that has never chatted answers an empty list.
            """,
            query: [projectQuery(required: true),
                    QueryParameter(name: "agent", required: true, schema: string, description: "Agent id or name."),
                    QueryParameter(name: "limit", required: false, schema: integer, description: "Newest messages to return; default 50.")],
            responses: [
                Status(code: 200, description: "The transcript tail, oldest first.", schema: ref("AgentTranscript")),
                errorStatus(400, "Missing ?project= or ?agent=."),
                errorStatus(404, "No such agent in this project."),
                errorStatus(409, "Project not open in Kiteloop.")
            ]
        )
    }

    /// The `/v1/memory/proposals…` family.
    private static func memoryDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .listMemoryProposals: return listMemoryProposalsDetail()
        case .approveMemoryProposal: return approveMemoryProposalDetail()
        case .rejectMemoryProposal: return rejectMemoryProposalDetail()
        default:
            preconditionFailure("\(route) is not a memory route")
        }
    }

    private static func listMemoryProposalsDetail() -> Detail {
        return Detail(
            id: "listMemoryProposals",
            summary: "List a project's pending memory proposals",
            description: """
            An agent's own propose_memory call, or a fact the librarian pass wants \
            merged, deleted or archived — everything a human would see on the Memory \
            tab's pending list, so a driver running Kiteloop headlessly can see what has \
            been proposed. Read-only: nothing here approves, rejects or edits a proposal, \
            and nothing not pending is reported.
            """,
            query: [projectQuery(required: true)],
            responses: [
                Status(code: 200, description: "Pending proposals, oldest first.", schema: ref("MemoryProposalList")),
                errorStatus(400, "Missing ?project=."),
                errorStatus(409, "Project not open in Kiteloop.")
            ]
        )
    }

    private static func approveMemoryProposalDetail() -> Detail {
        return Detail(
            id: "approveMemoryProposal",
            summary: "Approve a pending memory proposal",
            description: """
            Applies the proposal's operation to the agent's memory — adds the fact, \
            merges the named ones, deletes or archives one — and marks the proposal \
            approved. The same button the Memory tab offers a person, pressed remotely: \
            before this, that button was the only caller, so a proposal filed during an \
            unattended run could never be answered and the index could never accumulate \
            a fact. This is an operator answering, not a loop that approves its own \
            memory. Only a *pending* proposal can be approved, so answering the same id \
            twice is a 404 rather than a second write. A refusal stays a refusal: the \
            fact is written before the proposal is marked, so a write the index turns \
            away — the 50-fact cap reached, or the fact already covered — answers 422 \
            with the reason and leaves the proposal pending for a human to edit.
            """,
            requestBody: memoryProposalAnswerBody,
            responses: [
                Status(code: 200, description: "Applied, and the proposal marked approved.", schema: ref("MemoryProposalAnswer")),
                errorStatus(400, "Body is missing \"project\" or \"id\"."),
                errorStatus(404, "No pending memory proposal with that id in this project — it may have been answered already."),
                errorStatus(409, "Project not open in Kiteloop."),
                errorStatus(422, "The index refused the write — the fact cap is reached, the fact is already covered, or a named topic is gone. Nothing was written and the proposal is still pending.")
            ]
        )
    }

    private static func rejectMemoryProposalDetail() -> Detail {
        return Detail(
            id: "rejectMemoryProposal",
            summary: "Reject a pending memory proposal",
            description: """
            Marks the proposal rejected and takes it off the pending list, without \
            touching the agent's memory — the Memory tab's Reject button, pressed \
            remotely. Only a *pending* proposal can be rejected, so answering the same \
            id twice is a 404. The status is written to the proposal's own JSON before \
            it is reported, so a write that did not land answers 422 rather than a 200 \
            the next launch would contradict.
            """,
            requestBody: memoryProposalAnswerBody,
            responses: [
                Status(code: 200, description: "The proposal is marked rejected and no longer pending.", schema: ref("MemoryProposalAnswer")),
                errorStatus(400, "Body is missing \"project\" or \"id\"."),
                errorStatus(404, "No pending memory proposal with that id in this project — it may have been answered already."),
                errorStatus(409, "Project not open in Kiteloop."),
                errorStatus(422, "The status could not be written. The proposal is still pending.")
            ]
        )
    }

    // MARK: - Backlog: the queue, what moves it, and what it has produced

    /// The queue and everything read off it. Reading an item, moving one,
    /// stamping a template and reading the history are four different reasons
    /// to change, so each is its own switch below.
    private static func backlogDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .listBacklog, .backlogItemDetail, .backlogItemDiff:
            return backlogReadDetail(for: route)
        case .approveBacklogItem, .landBacklogItem, .moveBacklogItem, .setBacklogItemLane, .groomBacklogItem,
             .releaseBacklogItem, .refreshBacklogItem:
            return backlogWriteDetail(for: route)
        case .listTemplates, .stampTemplate, .fileBacklogItem:
            return filingDetail(for: route)
        case .listMetrics, .listEstimates, .listGrooming, .portfolioReport:
            return historyDetail(for: route)
        default:
            preconditionFailure("\(route) is not a backlog route")
        }
    }

    /// Reading the queue and one item in it; none of these write.
    private static func backlogReadDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .listBacklog: return listBacklogDetail()
        case .backlogItemDetail: return backlogItemDetail()
        case .backlogItemDiff: return backlogItemDiffDetail()
        default:
            preconditionFailure("\(route) is not a backlog-read route")
        }
    }

    private static func listBacklogDetail() -> Detail {
        return Detail(
            id: "listBacklog",
            summary: "List a project's backlog items",
            description: """
            Every item, plus `issues` — the lines the parser could not read as work. \
            A driver counting queue depth needs both: an item missing from the list \
            because its line is malformed is not work that does not exist. \
            `strandedWork` sweeps the done items for work still sitting on an \
            unmerged branch; it reports, and merges nothing.
            """,
            query: [projectQuery(required: true)],
            responses: [
                Status(code: 200, description: "Every item in the backlog, across all epics.", schema: ref("BacklogList")),
                errorStatus(400, "Missing ?project=."),
                errorStatus(409, "Project not open in Kiteloop.")
            ]
        )
    }

    private static func backlogItemDetail() -> Detail {
        return Detail(
            id: "backlogItemDetail",
            summary: "One backlog item, drilled into",
            description: """
            The item's line fields plus its groomed detail — What, How, the \
            acceptance criteria, out-of-scope list, notes and verify commands — \
            read from the detail file the gates read. An item with no detail \
            file answers the line fields alone.
            """,
            query: [projectQuery(required: true),
                    QueryParameter(name: "item", required: true, schema: string, description: "Backlog item id.")],
            responses: [
                Status(code: 200, description: "The item, in full.", schema: ref("ItemDetail")),
                errorStatus(400, "Missing ?project= or ?item=."),
                errorStatus(404, "No such backlog item."),
                errorStatus(409, "Project not open in Kiteloop.")
            ]
        )
    }

    private static func backlogItemDiffDetail() -> Detail {
        return Detail(
            id: "backlogItemDiff",
            summary: "The item's unmerged branch, as a reviewable diff",
            description: """
            What approving would merge: the diff between the project's current \
            HEAD and the item's autopilot branch (`kiteloop/<item-id>`), with a \
            `--stat` summary. This is what a human at the approval gate reads \
            before clearing it. 404 when no such branch exists — the item ran \
            in the live tree, or the branch was already merged and deleted. \
            `patch` is capped at 200000 characters; `truncated` says when the \
            cap bit.
            """,
            query: [projectQuery(required: true),
                    QueryParameter(name: "item", required: true, schema: string, description: "Backlog item id.")],
            responses: [
                Status(code: 200, description: "The branch's diff against HEAD.", schema: ref("ItemDiff")),
                errorStatus(400, "Missing ?project= or ?item=."),
                errorStatus(404, "No such backlog item, or the item has no branch."),
                errorStatus(409, "Project not open in Kiteloop.")
            ]
        )
    }

    /// The verbs that move an item: its gate, its place in the queue, its
    /// status, and the two that let a stalled one run again.
    private static func backlogWriteDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .approveBacklogItem, .landBacklogItem: return backlogGateDetail(for: route)
        case .moveBacklogItem: return moveBacklogItemDetail()
        case .setBacklogItemLane: return setBacklogItemLaneDetail()
        case .groomBacklogItem: return groomBacklogItemDetail()
        case .releaseBacklogItem: return releaseBacklogItemDetail()
        case .refreshBacklogItem: return refreshBacklogItemDetail()
        default:
            preconditionFailure("\(route) is not a backlog-write route")
        }
    }

    /// The two verbs that put work in the base.
    private static func backlogGateDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .approveBacklogItem: return approveBacklogItemDetail()
        case .landBacklogItem: return landBacklogItemDetail()
        default:
            preconditionFailure("\(route) is not a backlog-gate route")
        }
    }

    private static func approveBacklogItemDetail() -> Detail {
        return Detail(
            id: "approveBacklogItem",
            summary: "Resolve an item's human gate",
            description: "Approve moves the item to done; reject returns it to ready with the reason as feedback. Only valid from awaiting-approval.",
            requestBody: itemGateBody,
            responses: [
                Status(code: 200, description: "Gate resolved.", schema: ref("ItemGateResolution")),
                errorStatus(400, "Body is missing \"project\" or \"item\"."),
                errorStatus(404, "No such backlog item in this project."),
                errorStatus(409, "Project not open, or the item isn't awaiting approval.")
            ]
        )
    }

    private static func landBacklogItemDetail() -> Detail {
        return Detail(
            id: "landBacklogItem",
            summary: "Merge a done item's branch that never landed",
            description: """
            The merge half of an approval, taken later. An item reads `done` with \
            its work still on a branch when its gate cleared with \
            `autoMergeOnApproval` off — a `propose` project approved by \
            hand, or one whose gate changed before it landed — and `GET /v1/backlog`'s `strandedWork` names it. This lands that \
            branch through the same gate as an approval's merge: a clean merge and \
            a green verify of the merged tree — the item's own `verify:` and the \
            verify-map rules the branch reaches, both — on the configured base. The \
            item's status does not change; it was done. A branch the base already \
            holds, or an item with no branch, is 409 with the reason, not a failure. \
            Takes the operator's own token, like approve: landing a branch is a \
            person's call.
            """,
            requestBody: itemLandBody,
            responses: [
                Status(code: 200, description: "Landed.", schema: ref("ItemLanding")),
                errorStatus(400, "Body is missing \"project\" or \"item\"."),
                errorStatus(404, "No such backlog item in this project."),
                Status(code: 409, description: "Project not open, the item is not done, nothing to land, or the gate refused the merge — `reason` says which, and `verifyOutput` carries a failing verify's tail.", schema: ref("ItemLanding"))
            ]
        )
    }

    private static func moveBacklogItemDetail() -> Detail {
        return Detail(
            id: "moveBacklogItem",
            summary: "Reorder a backlog item — position is the queue's priority",
            description: """
            Moves an item in front of another (`before`), or to the top of its own \
            epic when `before` is omitted. The queue is document order — epics top to \
            bottom, items within an epic top to bottom — so this is prioritisation; \
            there is no priority field. A done item answers 409: order only matters \
            for work still in play. Nothing else about the item changes — status, \
            grooming and `needs:` edges stay as they were, and moving in front of an \
            item in another epic follows it there.
            """,
            requestBody: itemMoveBody,
            responses: [
                Status(code: 200, description: "Reordered.", schema: ref("ItemMove")),
                errorStatus(400, "Body is missing \"project\" or \"item\"."),
                errorStatus(404, "No such backlog item, or no such \"before\" item."),
                errorStatus(409, "Project not open, or the item is done.")
            ]
        )
    }

    private static func setBacklogItemLaneDetail() -> Detail {
        return Detail(
            id: "setBacklogItemLane",
            summary: "Put a backlog item in the now or later lane",
            description: """
            Marks an item `lane:now` or clears the mark (`later`). Every `now` item \
            runs before every `later` one; within a lane the file's order still \
            decides. The item stays where it is in its epic — status, grooming and \
            `needs:` edges are untouched. A done item answers 409: the lane only \
            matters for work still in play.
            """,
            requestBody: itemLaneBody,
            responses: [
                Status(code: 200, description: "The item's lane, before and after.", schema: ref("ItemLane")),
                errorStatus(400, "Body is missing \"project\", \"item\" or \"lane\", or the lane is neither now nor later."),
                errorStatus(404, "No such backlog item in this project."),
                errorStatus(409, "Project not open, or the item is done.")
            ]
        )
    }

    private static func groomBacklogItemDetail() -> Detail {
        return Detail(
            id: "groomBacklogItem",
            summary: "Promote a groomed draft to ready, send one back, or lift a block",
            description: """
            Moves a backlog item between `draft` and `ready` — the transition that had \
            no headless equivalent, so a driver grooming a night's work had to edit \
            BACKLOG.md on the shared branch by hand and rely on the file watcher. \
            `status` defaults to `ready`, because promoting is what this is for; pass \
            `draft` to take a promotion back. A `blocked` item may be lifted to either, its \
            reason kept as a Notes line. Otherwise an item that is running, in review, at a \
            gate or done answers 409, since every other transition belongs to the machinery that earns it. \
            Readiness itself is not asserted — DefinitionOfReady and GroundingCheck \
            still run at pickup, so an ungroomed item promoted here is skipped with the \
            failing clause named rather than run.
            """,
            requestBody: itemGroomBody,
            responses: [
                Status(code: 200, description: "Status set.", schema: ref("ItemGroom")),
                errorStatus(400, "Body is missing \"project\" or \"item\", or \"status\" is not \"ready\" or \"draft\"."),
                errorStatus(404, "No such backlog item in this project."),
                errorStatus(409, "Project not open, or the item is in a status this verb does not move.")
            ]
        )
    }

    private static func releaseBacklogItemDetail() -> Detail {
        return Detail(
            id: "releaseBacklogItem",
            summary: "Let a retired item be picked up again",
            description: """
            Lifts the retry ceiling's refusal on an item that produced nothing three \
            times running. Without this an item retired by the ceiling could never run \
            again — it cannot run, and only a run could clear the count. Re-grooming the \
            item releases it on its own (its attempts were made against wording it no \
            longer has); this is for re-attempting an item exactly as it stands. The \
            release is recorded in ~/.kiteloop/grooming.jsonl as a `released` record and \
            noted in the item's own file. Releasing an item that isn't retired is \
            allowed and answers `wasRetired: false`. The ceiling is not raised: three \
            more attempts that produce nothing retire it again.
            """,
            requestBody: itemReleaseBody,
            responses: [
                Status(code: 200, description: "Released.", schema: ref("ItemRelease")),
                errorStatus(400, "Body is missing \"project\" or \"item\"."),
                errorStatus(404, "No such backlog item in this project."),
                errorStatus(409, "Project not open in Kiteloop."),
                errorStatus(503, "No grooming ledger attached to record the release in.")
            ]
        )
    }

    private static func refreshBacklogItemDetail() -> Detail {
        return Detail(
            id: "refreshBacklogItem",
            summary: "Rebase a stale item sitting at the approval gate",
            description: """
            Starts the same bounded worker round autopilot runs on its own once the \
            project goes idle: merges the project's current branch into the item's, \
            resolves conflicts, re-runs the item's `verify:`, and commits. The item \
            never leaves `awaiting-approval` and the reviewer is not consulted again — \
            the merge carries no new intent, so `verify:` is the whole check. 409 when \
            the item isn't awaiting approval, has no branch to rebase, or is already \
            fresh; a round that fails is recorded like a retry-ceiling attempt, and a \
            third failure in a row retires the item with the ceiling's own note, though \
            it still stays at the gate for a human to resolve by hand.
            """,
            requestBody: itemRefreshBody,
            responses: [
                Status(code: 200, description: "Refresh round result.", schema: ref("ItemRefresh")),
                errorStatus(400, "Body is missing \"project\" or \"item\"."),
                errorStatus(404, "No such backlog item in this project."),
                errorStatus(409, "Project not open, the item isn't awaiting approval, has no branch, or is already fresh.")
            ]
        )
    }

    /// Filing new work: one item by hand, or a template's items at once.
    private static func filingDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .listTemplates: return listTemplatesDetail()
        case .stampTemplate: return stampTemplateDetail()
        case .fileBacklogItem: return fileBacklogItemDetail()
        default:
            preconditionFailure("\(route) is not a filing route")
        }
    }

    private static func fileBacklogItemDetail() -> Detail {
        return Detail(
            id: "fileBacklogItem",
            summary: "File one new backlog item as a draft",
            description: """
            Files the item at `draft` under `epic` (`Inbox` when none is named), with an \
            id slugged from the title and kept clear of every id the project has used, \
            and the `note`, when given, as its detail file's What. Answers 201 at once. \
            With `"groom": true` the same grooming pass the Mac's Groom button runs then \
            writes the detail, `verify:` and size it proposes; the item stays at `draft`, \
            so promoting it is still a person's step. `grooming` says whether that pass \
            started, or why it could not.
            """,
            requestBody: object([
                "project": described(string, "Project identifier."),
                "title": described(string, "The item's title."),
                "note": described(string, "What the item is about, written as its What."),
                "epic": described(string, "The epic to file under. Defaults to Inbox."),
                "groom": described(bool, "Groom the item after filing it. Defaults to false.")
            ], required: ["project", "title"]),
            responses: [
                Status(code: 201, description: "Filed.", schema: object([
                    "item": described(string, "The new item's id."),
                    "epic": string,
                    "status": described(string, "Always draft."),
                    "grooming": described(string, "started, not asked, or why grooming could not start.")
                ], required: ["item", "epic", "status", "grooming"])),
                errorStatus(400, "No project or title, a title holding the line's field separator, or a non-boolean groom."),
                errorStatus(409, "Project not open, or it has no backlog."),
                errorStatus(500, "The backlog or the detail file could not be written.")
            ]
        )
    }

    private static func listTemplatesDetail() -> Detail {
        return Detail(
            id: "listTemplates",
            summary: "List a project's backlog templates",
            description: """
            A template is a recurring multi-item process written down once — item lines \
            and their groomed detail bodies, with `{{variable}}` placeholders where each \
            run of the process differs. `variables` is what a stamp has to be told; a \
            `pattern` is a regular expression the value must match whole. Templates are \
            read from `templates/` beside the backlog file, and from `templates/` in the \
            project root when the backlog lives elsewhere — `directories` says where the \
            app looked, so an empty list is readable. A file that doesn't parse is listed \
            with its `error` rather than omitted: a missing name reads as "no such \
            template" and sends whoever wrote it looking in the wrong place.
            """,
            query: [projectQuery(required: true)],
            responses: [
                Status(code: 200, description: "The templates found.", schema: ref("TemplateList")),
                errorStatus(400, "Missing ?project=."),
                errorStatus(409, "Project not open in Kiteloop.")
            ]
        )
    }

    private static func stampTemplateDetail() -> Detail {
        return Detail(
            id: "stampTemplate",
            summary: "Stamp a template into backlog items",
            description: """
            Previews by default; files with `"apply": true` and answers 201. Filing goes \
            through the same path a coordinator filing takes, so each item lands as a \
            backlog line plus its `backlog/<id>.md`, with the template's `needs:` edges \
            ordering them, and faces the same two gates — an item that fails \
            Definition-of-Ready or the grounding check is filed as `draft` with the \
            reason in its `gates` and its Notes, rather than queued. A variable that \
            fails its pattern, and an id already in the backlog, refuse the **whole** \
            stamp with 422 and write nothing: half a checklist is worse than none, since \
            the missing half is invisible. That collision refusal is also the guard \
            against filing the same release twice.
            """,
            requestBody: object([
                "project": described(string, "Project identifier."),
                "template": described(string, "Template name — the file's stem under templates/."),
                "variables": described(["type": "object", "additionalProperties": string],
                                       "Values by variable name. A JSON number is read as its text."),
                "apply": described(bool, "File the items. Defaults to false, which previews them.")
            ], required: ["project", "template"]),
            responses: [
                Status(code: 200, description: "The preview — what would be filed.", schema: ref("TemplateStamp")),
                Status(code: 201, description: "Filed.", schema: ref("TemplateStamp")),
                errorStatus(400, "Body is missing \"project\"/\"template\", or a variable isn't a string."),
                errorStatus(404, "No template by that name in this project."),
                errorStatus(409, "Project not open in Kiteloop."),
                errorStatus(422, "The whole stamp was refused — the template doesn't parse, a variable is missing or fails its pattern, or a stamped id is already in the backlog. Nothing was written."),
                errorStatus(500, "A write failed part-way through. The response names how many items landed.")
            ]
        )
    }

    /// What the queue has already produced — the durable ledgers, and the
    /// portfolio report aggregated from them.
    private static func historyDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .listMetrics: return listMetricsDetail()
        case .listEstimates: return listEstimatesDetail()
        case .listGrooming: return listGroomingDetail()
        case .portfolioReport: return portfolioReportDetail()
        default:
            preconditionFailure("\(route) is not a history route")
        }
    }

    private static func listMetricsDetail() -> Detail {
        return Detail(
            id: "listMetrics",
            summary: "Recent measured runs, newest first",
            description: """
            The durable counterpart to GET /v1/runs — one record per finished item, \
            read from ~/.kiteloop/task-metrics.jsonl, so it survives restarts and spans \
            every project unless narrowed with ?project=. `escapedDefects` and \
            `firstPassRate` cover the whole history rather than the returned page; \
            `openingContextByRole` — p50/p90 of what each role was sent before it had \
            done anything — covers the returned page only, so ?limit= is its window.
            """,
            query: [projectQuery(required: false), historyLimitQuery(default: 20)],
            responses: [
                Status(code: 200, description: "Measured runs.", schema: ref("MetricList")),
                errorStatus(400, "\"limit\" isn't an integer in 1…200."),
                errorStatus(409, "Project not open in Kiteloop."),
                errorStatus(503, "No metric store attached.")
            ]
        )
    }

    private static func listEstimatesDetail() -> Detail {
        return Detail(
            id: "listEstimates",
            summary: "Latest pre-run estimate for each scoped item",
            description: "Scoping an item again appends rather than replaces; only the newest estimate per item is reported.",
            query: [projectQuery(required: false), historyLimitQuery(default: 20)],
            responses: [
                Status(code: 200, description: "Current estimates.", schema: ref("EstimateList")),
                errorStatus(400, "\"limit\" isn't an integer in 1…200."),
                errorStatus(409, "Project not open in Kiteloop."),
                errorStatus(503, "No metric store attached.")
            ]
        )
    }

    private static func listGroomingDetail() -> Detail {
        return Detail(
            id: "listGrooming",
            summary: "Recent grooming records, newest first",
            description: """
            What happened to items *before* they ran — each filing, and each refusal by \
            a pre-run check (definition-of-ready, grounding-check, retry-ceiling) with \
            the clause that failed. Read from ~/.kiteloop/grooming.jsonl, so it survives \
            restarts and spans every project unless narrowed with ?project=. This is how \
            a driver tells a queue that drained because items were refused from one that \
            drained because the work is done.
            """,
            query: [projectQuery(required: false), historyLimitQuery(default: 20)],
            responses: [
                Status(code: 200, description: "Grooming records.", schema: ref("GroomingList")),
                errorStatus(400, "\"limit\" isn't an integer in 1…200."),
                errorStatus(409, "Project not open in Kiteloop."),
                errorStatus(503, "No grooming ledger attached.")
            ]
        )
    }

    private static func portfolioReportDetail() -> Detail {
        return Detail(
            id: "portfolioReport",
            summary: "What a period of unattended work produced, per project",
            description: """
            The aggregation behind the coordinator panel: merged ÷ filed per project \
            over the window, with the causes behind the rejections, the spend and the \
            idle time. Served rather than left to the caller because the rate has a \
            rule worth not re-deriving — a period with runs but no filings falls back \
            to merged ÷ run, and every rate carries the `basis` that says which of the \
            two it is.
            """,
            query: [QueryParameter(name: "hours", required: false,
                                   schema: boundedInteger(min: 1, max: 720),
                                   description: "Window to report on, 1…720. Defaults to 24.")],
            responses: [
                Status(code: 200, description: "The period.", schema: ref("PortfolioReport")),
                errorStatus(400, "\"hours\" isn't an integer in 1…720."),
                errorStatus(503, "No metric store or no grooming ledger attached; the message says which.")
            ]
        )
    }

    // MARK: - Queue: one project's autopilot, and the fleet-wide hold

    /// What advances the queues: a project's own autopilot, and the hold
    /// taken across every project at once.
    private static func queueDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .getAutopilot, .setAutopilot, .resetAutopilot,
             .pauseAutopilot, .resumeAutopilot:
            return autopilotDetail(for: route)
        case .fleetStatus, .quiesceFleet, .resumeFleet, .usage:
            return fleetDetail(for: route)
        default:
            preconditionFailure("\(route) is not a queue route")
        }
    }

    /// The `/v1/autopilot…` family — one project's configuration and its queue.
    private static func autopilotDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .getAutopilot: return getAutopilotDetail()
        case .setAutopilot: return setAutopilotDetail()
        case .resetAutopilot: return resetAutopilotDetail()
        case .pauseAutopilot: return pauseAutopilotDetail()
        case .resumeAutopilot: return resumeAutopilotDetail()
        default:
            preconditionFailure("\(route) is not an autopilot route")
        }
    }

    private static func getAutopilotDetail() -> Detail {
        return Detail(
            id: "getAutopilot",
            summary: "Read a project's autopilot configuration and run state",
            description: """
            The configuration, plus a `run` block saying whether the project is running \
            an item, which one and since when. `run` is derived from the same check that \
            refuses a POST /v1/runs with 409, so the two can never disagree. Absent from \
            the PUT and reset responses, which answer with what they wrote.
            """,
            query: [projectQuery(required: true)],
            responses: [
                Status(code: 200, description: "The full configuration and run state.",
                       schema: ref("AutopilotStatus")),
                errorStatus(400, "Missing ?project=."),
                errorStatus(409, "Project not open in Kiteloop.")
            ]
        )
    }

    private static func setAutopilotDetail() -> Detail {
        return Detail(
            id: "setAutopilot",
            summary: "Configure worker, reviewer and the run knobs",
            description: """
            Every field except `project` is optional and an omitted one is left \
            unchanged. `worker` and `reviewer` take an agent id or a name. An empty \
            `worker` is a 400 rather than an unassignment; a null or empty \
            `reviewer` clears it — no separate reviewer. Both are resolved \
            before anything is written, so a body naming one known and one unknown \
            agent changes neither. `coordinator` is deprecated and ignored — the \
            per-project persona picker retired, so a body carrying it is tolerated \
            for callers written against that, but nothing is written and no reply \
            carries it. `autonomy` reads and writes `autonomousWorkEnabled` and \
            `approvalGate` together. `approveReviewPassedRuns` and \
            `autoMergeOnApproval` are deprecated, read for one release and mapped \
            onto `approvalGate`: `land` when both end up true, a switch the body \
            leaves out keeping its current value, otherwise `propose`. \
            `approvalGate` wins over them, and `autonomy` over everything. \
            Responds with the full configuration, the same shape GET returns.
            """,
            requestBody: object([
                "project": described(string, "Project identifier."),
                "worker": described(string, "Worker agent id or name."),
                "reviewer": described(nullable(string), "Reviewer agent id or name; null or \"\" clears it, so a run goes from the worker straight to the gates."),
                "coordinator": described(nullable(string), "Deprecated and ignored; accepted so callers written against the retired per-project persona picker keep working."),
                "autonomy": described(enumOf(["off", "propose", "land"]), "How far this project may go on its own. off: never picked up unattended. propose: unattended runs start, and a review-passed run parks at the approval gate. land: a review-passed run is approved without asking and merged. One dial for autonomousWorkEnabled and approvalGate below."),
                "approvalGate": described(enumOf(["propose", "land"]), "What happens to a run the reviewer passed. propose: it parks at the approval gate, and a person's approval does not merge it. land: it is approved without a person and merged. Independent of autonomousWorkEnabled, so land with unattended runs off is a project whose hand-started runs land themselves."),
                "useWorktree": described(bool, "Deprecated and ignored; accepted so callers written against it keep working. Not a setting: a project whose root is a git repository always runs its items in a worktree, and one that is not runs in the live tree."),
                "maxRetries": described(integer, "Worker/reviewer rounds one item gets in a run, clamped to 1…10."),
                "stallTimeoutMinutes": described(integer, "Deprecated and ignored; accepted so callers written against it keep working. No longer a setting: the worker/reviewer node's deadline is this project's own p95 worker-phase duration plus half again, floored at 15 minutes and capped at 60, and the reply answers with that derived value."),
                "refuteRoundEnabled": described(bool, "Retired and ignored; accepted so callers written against the removed refute round keep working."),
                "budgetUSD": described(nullable(number), "This project's one budget — a daily ceiling that also bounds a sitting; positive, or null to clear it. Not the portfolio's — that is PUT /v1/coordinator/scheduling. Replaces perItemCostCapUSD, sessionCostCapUSD, costCapMargin and dailyBudgetUSD: the per-item ceiling is no longer a setting, it is the ledger's own prediction for the item's size once there is enough evidence for one."),
                "autoMergeOnApproval": described(bool, "Deprecated in favour of approvalGate, read for one release: mapped onto it with approveReviewPassedRuns — land only when both end up true."),
                "autoMergeVerifyCommand": described(nullable(string), "Retired and ignored; accepted so callers written against it keep working. No longer a setting: the merge gate runs the verify map's rules, and a rule matching every path (glob \"**\") is what this was."), "autoMergeVerifyTimeoutMinutes": described(integer, "Deprecated and ignored; accepted so callers written against it keep working. No longer a setting: the merge gate's deadline is this project's own p95 verify duration plus half again, floored at 10 minutes, and the reply answers with that derived value."), "worktreeSetupCommand": described(nullable(string), "The command run in every worktree Kiteloop creates for this project — the worker's, the merge gate's scratch tree, the rebase scratch tree — right after checkout and before anything else runs there. null or \"\" clears it, back to nothing running (today's behaviour). A non-zero exit or a timeout refuses the merge or blocks the item, naming the command and its output; never retried."), "baseBranch": described(nullable(string), "The local branch runs fork from and land on, and pull requests open against. null or \"\" clears it, back to the checkout's own HEAD. A name no local branch has refuses the next run at start."),
                "openPullRequest": described(bool, "Push the branch, open a pull request for a run that reaches the approval gate, and follow its checks until they are green. Never merges."),
                "approveReviewPassedRuns": described(bool, "Deprecated in favour of approvalGate, read for one release: mapped onto it with autoMergeOnApproval — land only when both end up true. Clear the approval gate without a human for an item the reviewer passed. Off by default. A rejected or blocked run, a run salvaged by its own verify:, and an item whose auto-merge was refused all still wait for a person."),
                "autonomousWorkEnabled": described(bool, "Deprecated in favour of autonomy; still settable on its own. This project's consent to unattended work. Off by default; only with it on do the fleet scheduler and the grooming loop pick the project up on their own. A human start never consults it."),
                "protectedPaths": described(array(of: string), "Retired and ignored; accepted so callers written against the removed protected-paths setting keep working.")
            ], required: ["project"]),
            responses: [
                Status(code: 200, description: "The configuration after the write.", schema: ref("AutopilotConfig")),
                errorStatus(400, "Body is missing \"project\", or names an agent this project doesn't have."),
                errorStatus(409, "Project not open in Kiteloop.")
            ]
        )
    }

    private static func resetAutopilotDetail() -> Detail {
        return Detail(
            id: "resetAutopilot",
            summary: "Reset caps, margin and flags to their defaults",
            description: "The worker/reviewer assignment survives, so autopilot stays runnable. Refused while a run is in flight — the caps are being enforced against it.",
            requestBody: projectBody,
            responses: [
                Status(code: 200, description: "The configuration after the reset.", schema: ref("AutopilotConfig")),
                errorStatus(400, "Body is missing \"project\"."),
                errorStatus(409, "Project not open, or autopilot isn't idle.")
            ]
        )
    }

    private static func pauseAutopilotDetail() -> Detail {
        return Detail(
            id: "pauseAutopilot",
            summary: "Hold the queue after the item in flight",
            description: "Lands at the next item boundary — the run in flight still reaches its gate. Pausing an already-paused queue is a no-op, not a 409, so a retry after a dropped connection is safe.",
            requestBody: projectBody,
            responses: [
                Status(code: 200, description: "The queue is paused.", schema: ref("AutopilotPaused")),
                errorStatus(400, "Body is missing \"project\"."),
                errorStatus(409, "Project not open, or autopilot isn't running.")
            ]
        )
    }

    private static func resumeAutopilotDetail() -> Detail {
        return Detail(
            id: "resumeAutopilot",
            summary: "Lift a pause, whichever way it was taken",
            description: """
            Pausing is one act — the human's paused switch on the fleet board reads the same as \
            `POST /v1/autopilot/pause` — so this lifts whichever of the two, or both, are holding the \
            project. `resumed` says which: `"paused"`, `"autopilot"`, or `"both"`.

            A project held only by the fleet board's switch has no queue to pick back up, so that \
            case answers 200 once the switch is cleared. Any case where the autopilot itself was \
            paused still answers 202 immediately — the remaining items run in the background.
            """,
            requestBody: projectBody,
            responses: [
                Status(code: 200, description: "The project's paused switch was cleared; there was no queue to resume.",
                       schema: ref("AutopilotResumedProject")),
                Status(code: 202, description: "Resuming.", schema: ref("AutopilotResuming")),
                errorStatus(400, "Body is missing \"project\"."),
                errorStatus(409, "Project not open, or the project isn't paused either way.")
            ]
        )
    }

    /// The `/v1/fleet…` family — the hold that spans every project.
    private static func fleetDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .fleetStatus: return fleetStatusDetail()
        case .quiesceFleet: return quiesceFleetDetail()
        case .resumeFleet: return resumeFleetDetail()
        case .usage: return usageDetail()
        default:
            preconditionFailure("\(route) is not a fleet route")
        }
    }

    private static func usageDetail() -> Detail {
        let rateLimit = object([
            "status": described(string, "allowed while under the limit; anything else is a warning, rejected a refusal."),
            "window": described(nullable(string), "The window the status is about — five_hour, seven_day."),
            "resetsAt": described(nullable(string), "When the window resets, ISO 8601."),
            "utilization": described(nullable(number), "That window's share used, 0…1.")
        ], required: ["status"])
        let spend = object([
            "hours": integer,
            "totalUSD": number,
            "projects": array(of: object(["project": string, "spendUSD": number], required: ["project", "spendUSD"])),
            "omittedProjects": array(of: string)
        ], required: ["hours", "totalUSD", "projects"])
        return Detail(
            id: "usage",
            summary: "How close the agents are to their rate limit, and where the day's spend went",
            description: """
            `rateLimit` is the reading closest to its limit among every open project's \
            agents — a refusal first, then a warning, then the highest share used — or \
            null when no agent has reported one this launch; `agentsReporting` says how \
            many have. `spend` is the last 24 hours per project, busiest first, from the \
            same report as GET /v1/report; null when this Mac keeps no metrics.
            """,
            responses: [
                Status(code: 200, description: "The reading.", schema: object([
                    "rateLimit": described(nullable(rateLimit), "The reading closest to its limit."),
                    "agentsReporting": integer,
                    "spend": described(nullable(spend), "The last day's spend per project.")
                ], required: ["rateLimit", "agentsReporting", "spend"]))
            ]
        )
    }

    private static func fleetStatusDetail() -> Detail {
        return Detail(
            id: "fleetStatus",
            summary: "Is the fleet holding, and has the last run finished?",
            description: """
            One answer in place of a `GET /v1/projects` poll: whether new work is being \
            refused, and how many runs are still finishing. A restart strands nothing \
            exactly when `quiesced` and `drained` are both true. Starts and stops nothing.
            """,
            responses: [
                Status(code: 200, description: "Where the fleet is.", schema: ref("FleetReading"))
            ]
        )
    }

    private static func quiesceFleetDetail() -> Detail {
        return Detail(
            id: "quiesceFleet",
            summary: "Stop the whole fleet taking new work, and wait for it to drain",
            description: """
            Closes the gate first — while it is closed `POST /v1/runs` is refused with 409 \
            and the autonomous scheduler holds — then pauses every queue that is advancing. \
            Runs in flight are not interrupted; they finish at their own gate. Send \
            `waitSeconds` to have the call return only once the last one has ended, which is \
            what this exists for: polling loses the window, because drivers start the next \
            item within seconds of one ending. A wait that times out is still a 200, with \
            `drained: false` and a count of what is left. Idempotent — a project already \
            paused is left alone and left out of the ledger, so a retry cannot cause \
            `POST /v1/fleet/resume` to start a queue somebody else was holding. \
            Not persisted: a restart clears the hold.
            """,
            requestBody: object([
                "waitSeconds": described(["type": "number", "minimum": 0, "maximum": 600],
                                         "Wait up to this long for the last run to finish. "
                                       + "Omitted or 0 answers immediately.")
            ], required: []),
            responses: [
                Status(code: 200, description: "The fleet is held; `drained` says whether anything is still finishing.",
                       schema: ref("FleetReading")),
                errorStatus(400, "Body isn't a JSON object, or \"waitSeconds\" is out of 0…600.")
            ]
        )
    }

    private static func resumeFleetDetail() -> Detail {
        return Detail(
            id: "resumeFleet",
            summary: "Lift the hold and pick the held queues back up",
            description: """
            Reopens the gate and resumes exactly the projects the quiesce paused — never one \
            that was already paused when it arrived. A ledgered project that is no longer \
            paused is reported under `skipped` rather than resumed; after the restart the \
            quiesce was taken for, that is all of them, since the ledger is in memory and the \
            autopilots come back idle. Always 200, `resumed` empty when there was nothing to \
            pick up.
            """,
            responses: [
                Status(code: 200, description: "The hold is lifted.", schema: ref("FleetResumed"))
            ]
        )
    }

    // MARK: - Coordinator: the loops that fill and start work

    /// The `/v1/coordinator…` family: the two live loops, and the three
    /// routes advisory mode left behind.
    private static func coordinatorDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .getCoordinatorRefill, .setCoordinatorRefill,
             .getCoordinatorScheduling, .setCoordinatorScheduling:
            return coordinatorLoopDetail(for: route)
        case .listProposals, .approveProposal, .dismissProposal:
            return retiredProposalDetail(for: route)
        default:
            preconditionFailure("\(route) is not a coordinator route")
        }
    }

    /// The queue-refill loop and the autonomous run scheduler, read and written.
    private static func coordinatorLoopDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .getCoordinatorRefill: return getCoordinatorRefillDetail()
        case .setCoordinatorRefill: return setCoordinatorRefillDetail()
        case .getCoordinatorScheduling: return getCoordinatorSchedulingDetail()
        case .setCoordinatorScheduling: return setCoordinatorSchedulingDetail()
        default:
            preconditionFailure("\(route) is not a coordinator-loop route")
        }
    }

    private static func getCoordinatorRefillDetail() -> Detail {
        return Detail(
            id: "getCoordinatorRefill",
            summary: "Read the queue-refill loop and its recent passes",
            description: """
            Pass history is in memory and bounded by `historyLimit`, so it starts empty \
            after a restart. A hold is reported like any other pass, with the reason it held.
            """,
            query: [historyLimitQuery(default: 20)],
            responses: [
                Status(code: 200, description: "Settings, budget and recent passes newest first.", schema: ref("RefillStatus")),
                errorStatus(400, "\"limit\" isn't an integer in 1…200."),
                errorStatus(503, "The app window isn't running.")
            ]
        )
    }

    private static func setCoordinatorRefillDetail() -> Detail {
        return Detail(
            id: "setCoordinatorRefill",
            summary: "Switch the queue-refill loop on, and set its ceilings, cadence and policy",
            description: """
            Each field is optional; an omitted one is left alone. Note the response is \
            the settings only — not the pass history GET returns. `enabled` is \
            applied last, so switching on starts against the ceilings sent with it. \
            `mode` — advisory mode's retired knob — is deprecated: it is tolerated \
            and ignored, so a driver still sending it keeps working.

            `dailyBudgetUSD` and `maxPasses` are two ceilings on the same loop and \
            either one stops grooming, so raising the one that wasn't going to bind \
            changes nothing: read `budget` from GET to see which is nearer.

            When neither ceiling is binding and queues still run dry, the lever is the \
            policy rather than the pacing: `maxProjectsPerPass` is how much of the fleet \
            one pass serves, and shortening `checkIntervalSeconds` instead spends a pass \
            per tick on projects that needed nothing.
            """,
            requestBody: object([
                "enabled": bool,
                "mode": described(coordinatorMode, "Deprecated — advisory mode retired. Tolerated and ignored."),
                "dailyBudgetUSD": described(nullable(number), "Positive, or null to clear the ceiling."),
                "maxPasses": described(boundedInteger(min: 1), "How many grooming passes the day allows — the other ceiling on the same loop, and the one that is usually reached first. Positive; there is no null to clear it. Persisted as `coordinatorMaxPassesPerDay`, so it survives a restart."),
                "checkIntervalSeconds": described(integer, "How often the loop looks, 60…86400. Restarts the timer, so the next pass comes on the new cadence. Not persisted."),
                "threshold": described(boundedInteger(min: 0, max: 50), "Ready-queue depth below which a project gets a refill. 0…50."),
                "targetDepth": described(boundedInteger(min: 1, max: 50), "The depth a refill tops a queue back up to. 1…50; held at or above `threshold`, or a refill would never settle."),
                "maxItemsPerPass": described(boundedInteger(min: 1, max: 50), "The most items one pass drafts for one project, 1…50. Below `targetDepth` it is what actually decides, and an emptied queue then needs several passes to reach the target."),
                "maxProjectsPerPass": described(boundedInteger(min: 1, max: 50), "The most projects one pass serves, 1…50. At 1 the cadence divides by the fleet size, which is what left two of three projects at ready=0 while grooming had spent 1 of 150 passes.")
            ], required: []),
            requestBodyRequired: false,
            responses: [
                Status(code: 200, description: "The settings after the write.", schema: ref("RefillSettings")),
                errorStatus(400, "Body isn't a JSON object, or a field has the wrong type or value. A rejected policy field names the range it would have taken, and leaves the whole policy as it was."),
                errorStatus(503, "No refill loop attached.")
            ]
        )
    }

    private static func getCoordinatorSchedulingDetail() -> Detail {
        return Detail(
            id: "getCoordinatorScheduling",
            summary: "Read the autonomous run scheduler and what it has started",
            description: """
            Start history is bounded by `historyLimit` and read back at launch from \
            ~/.kiteloop/coordinator-starts.jsonl, so it survives a restart; a start whose \
            process died mid-run reads `interrupted`.
            """,
            query: [historyLimitQuery(default: 20)],
            responses: [
                Status(code: 200, description: "Switch, holds, budget and recent starts newest first.", schema: ref("SchedulingStatus")),
                errorStatus(400, "\"limit\" isn't an integer in 1…200."),
                errorStatus(503, "No scheduler attached.")
            ]
        )
    }

    private static func setCoordinatorSchedulingDetail() -> Detail {
        return Detail(
            id: "setCoordinatorScheduling",
            summary: "Switch autonomous run starts on/off; set the portfolio's daily ceiling; clear every autonomous hold",
            description: """
            Every field is optional; sending none reports the state unchanged. \
            `dailyBudgetUSD` is the **portfolio** ceiling in ~/.kiteloop/global-config.json — \
            the one a project's own budget can never license it past. It is written before \
            `enabled`, so one call can raise the budget and switch the loop back on. \
            Responds with the same payload as GET, at the default limit.
            """,
            requestBody: object([
                "enabled": described(bool, "The kill switch. Switching it on also clears every hold."),
                "dailyBudgetUSD": described(nullable(number), "The portfolio-wide daily ceiling; positive, or null to clear it."),
                "resetBreaker": described(bool, "true clears every autonomous hold; false does nothing."),
                "maxConcurrentRuns": described(boundedInteger(min: 1, max: 8), "How many autonomous runs the fleet may have in flight at once, across projects; each project still runs one at a time. Persisted.")
            ], required: []),
            requestBodyRequired: false,
            responses: [
                Status(code: 200, description: "The scheduler state after the write.", schema: ref("SchedulingStatus")),
                errorStatus(400, "Body isn't a JSON object, a boolean field isn't a boolean, or \"dailyBudgetUSD\" isn't a positive number or null."),
                errorStatus(503, "No scheduler attached.")
            ]
        )
    }

    /// The three retired proposals routes, which answer 410 and nothing else.
    private static func retiredProposalDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .listProposals: return listProposalsDetail()
        case .approveProposal: return approveProposalDetail()
        case .dismissProposal: return dismissProposalDetail()
        default:
            preconditionFailure("\(route) is not a retired proposals route")
        }
    }

    private static func listProposalsDetail() -> Detail {
        return Detail(
            id: "listProposals",
            summary: "Retired — the advisory-mode proposals inbox is gone",
            description: proposalsRetiredDescription,
            responses: [proposalsGone]
        )
    }

    private static func approveProposalDetail() -> Detail {
        return Detail(
            id: "approveProposal",
            summary: "Retired — the advisory-mode proposals inbox is gone",
            description: proposalsRetiredDescription,
            responses: [proposalsGone]
        )
    }

    private static func dismissProposalDetail() -> Detail {
        return Detail(
            id: "dismissProposal",
            summary: "Retired — the advisory-mode proposals inbox is gone",
            description: proposalsRetiredDescription,
            responses: [proposalsGone]
        )
    }

    // MARK: - Runs: starting one, watching it, and intervening

    /// The `/v1/runs…` family. Watching a run and acting on one change for
    /// different reasons, so they are two switches.
    private static func runDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .startRun, .approveRun, .cancelRun, .steerRun: return runWriteDetail(for: route)
        case .listRuns, .runStatus, .runResult, .runEvents, .runLog: return runReadDetail(for: route)
        default:
            preconditionFailure("\(route) is not a run route")
        }
    }

    /// Starting a run, and the three interventions on one in flight.
    private static func runWriteDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .startRun: return startRunDetail()
        case .approveRun: return approveRunDetail()
        case .cancelRun: return cancelRunDetail()
        case .steerRun: return steerRunDetail()
        default:
            preconditionFailure("\(route) is not a run-write route")
        }
    }

    private static func startRunDetail() -> Detail {
        return Detail(
            id: "startRun",
            summary: "Start a backlog item",
            description: """
            One run at a time per project. A request arriving while the previous run is \
            still tearing down waits up to 30s for it rather than 409ing immediately. \
            Answers 202 with the workflow execution id — the runId every other run \
            endpoint takes, and which keeps answering after a restart as a historical \
            record. A run that has not named itself within the spin-up window answers \
            202 with status "starting" and no runId: it was accepted and is running, \
            and the id can be read from GET /v1/autopilot (run.runId). A refusal is \
            reported only when a gate actually refused, in that gate's words.
            """,
            requestBody: object([
                "project": described(string, "Project identifier."),
                "item": described(string, "Backlog item id."),
                "itemId": described(string, "Accepted as an alias for \"item\".")
            ], required: ["project"], anyOfRequired: [["item"], ["itemId"]]),
            responses: [
                Status(code: 202, description: "The run has started, or was accepted and is still spinning up.", schema: ref("RunStarted")),
                errorStatus(400, "Body is missing \"project\" or \"item\"."),
                errorStatus(404, "No such backlog item in this project."),
                errorStatus(409, "A condition of the moment, not a verdict on the item: project not open, autopilot still busy, worker/reviewer not configured, agents without a session, or a spent daily ceiling. Come back."),
                errorStatus(422, "The pickup gates refused this item — not ready (Definition-of-Ready), not grounded, retired by the retry ceiling, or in a status autopilot doesn't run. True until the item is re-groomed, so a driver may drop it.")
            ]
        )
    }

    private static func approveRunDetail() -> Detail {
        return Detail(
            id: "approveRun",
            summary: "Resolve this run's pending gate",
            description: """
            Resolves whichever gate this run is holding: a mid-workflow human-approval \
            node takes priority, otherwise the backlog item's sign-off gate. The two \
            answer different shapes — `gate` tells them apart. An absent body approves.
            """,
            requestBody: object([
                "approve": described(bool, "Defaults to true when absent."),
                "approved": described(bool, "Accepted as an alias for \"approve\"."),
                "note": described(string, "Reason, recorded as feedback on a rejection.")
            ], required: []),
            requestBodyRequired: false,
            responses: [
                Status(code: 200, description: "The gate has been resolved.",
                       schema: ["oneOf": [ref("WorkflowGateResolution"), ref("ItemGateResolution")]]),
                errorStatus(404, "No run with this id, live or on record; or its item is gone."),
                errorStatus(409, "The run has no pending approval — including a run that is only on record, whose item gate is resolved with POST /v1/backlog/approve instead.")
            ]
        )
    }

    private static func cancelRunDetail() -> Detail {
        return Detail(
            id: "cancelRun",
            summary: "Abandon a run that is still in flight",
            description: """
            Interrupts the agent holding the current node, cancels the execution and \
            stops the project's queue — so it abandons the queue, not just this item. \
            202: autopilot notices on its next poll (~2s) and only then puts the item \
            back to ready. Poll GET /v1/runs/{id}/result for the unwound state.
            """,
            responses: [
                Status(code: 202, description: "Cancellation has been requested.", schema: ref("RunCancelling")),
                errorStatus(404, "No run with this id, live or on record."),
                errorStatus(409, "The run has already finished, or is only on record and has nothing left to cancel.")
            ]
        )
    }

    private static func steerRunDetail() -> Detail {
        return Detail(
            id: "steerRun",
            summary: "Hand this run's worker a note",
            description: """
            A short note for the worker of the run in flight, delivered at its next turn \
            boundary — the intervention that is neither cancelling nor waiting. It is \
            advice: it cannot approve the work, raise a cap, change the item or reach the \
            reviewer, and the item's What / How / Validation still govern the review. \
            Trimmed, and truncated at 1000 characters rather than refused; the reply \
            carries the note as it was queued. Every note is recorded — the run log, the \
            phase log and the item's Notes.
            """,
            requestBody: object([
                "note": described(string, "The note, as the worker will be shown it. Trimmed; truncated at 1000 characters.")
            ], required: ["note"]),
            responses: [
                Status(code: 200, description: "The note is queued for the worker.", schema: ref("RunSteer")),
                errorStatus(400, "Body is missing \"note\"."),
                errorStatus(404, "No run with this id, live or on record."),
                errorStatus(409, "There is no worker to hand it to — the reviewer holds the run, the run is over, it is no longer the one in flight, or the note was only whitespace.")
            ]
        )
    }

    /// Watching a run: the listing, the polls, the stream and the log.
    private static func runReadDetail(for route: ControlRoute) -> Detail {
        switch route {
        case .listRuns: return listRunsDetail()
        case .runStatus: return runStatusDetail()
        case .runResult: return runResultDetail()
        case .runEvents: return runEventsDetail()
        case .runLog: return runLogDetail()
        default:
            preconditionFailure("\(route) is not a run-read route")
        }
    }

    private static func listRunsDetail() -> Detail {
        return Detail(
            id: "listRuns",
            summary: "List tracked runs, newest first",
            description: "Runs this app process started, plus what earlier processes wrote to `~/.kiteloop/control-runs.jsonl` — the latter marked `historical: true`. A run whose project has since been closed reads `state: \"unknown\"`. Unlike the other listings, `?project=` here accepts a project that is **not** open — a run record outlives its project — and `?limit=` bounds only the historical rows, so a live run is always listed.",
            query: [projectQuery(required: false), historyLimitQuery(default: 20)],
            responses: [
                Status(code: 200, description: "Tracked runs.", schema: ref("RunList")),
                errorStatus(400, "\"limit\" isn't an integer in 1…200.")
            ]
        )
    }

    private static func runStatusDetail() -> Detail {
        return Detail(
            id: "getRunStatus",
            summary: "Poll a run's status",
            description: """
            `currentNode` and `executionStatus` are present while the workflow execution \
            still exists; `approvalQuestion` only while a workflow gate is pending. A run \
            this process is not running answers from its durable record instead \
            (`historical: true`): the closing readout, an empty `events` list, and \
            `autopilot` only while its project is open.
            """,
            responses: [
                Status(code: 200, description: "Current status, with this run's last 20 events.", schema: ref("RunStatus")),
                errorStatus(404, "No run with this id, live or on record.")
            ]
        )
    }

    private static func runResultDetail() -> Detail {
        return Detail(
            id: "getRunResult",
            summary: "Read a run's outcome",
            description: """
            202 until the run has landed, then 200 with the result. Poll this rather than \
            parsing the event stream for completion. A run from before an app restart \
            answers 200 from its durable record (`historical: true`) — `state: \
            "interrupted"` when the restart is what ended it — so a poll loop is released \
            rather than parked on a run nothing is driving.
            """,
            responses: [
                Status(code: 200, description: "The run has finished, or is a historical record.", schema: ref("RunResult")),
                Status(code: 202, description: "Still running, or paused at a human gate.", schema: ref("RunPending")),
                errorStatus(404, "No run with this id, live or on record.")
            ]
        )
    }

    private static func runEventsDetail() -> Detail {
        return Detail(
            id: "streamRunEvents",
            summary: "Live event stream (SSE)",
            description: """
            Backfills this run's events, then streams new ones and closes on the \
            terminal event. If the run had already ended, the backfill is the whole \
            stream and the connection closes immediately. A `: keepalive` comment goes \
            out every 15s so an idle stream doesn't look dead.
            """,
            responses: [
                Status(code: 200,
                       description: "An SSE stream. Each frame's data is a JSON object: {ts, type, source, payload}.",
                       schema: described(string, "SSE frames, newline-delimited."),
                       contentType: "text/event-stream"),
                errorStatus(404, "No run with this id, live or on record."),
                errorStatus(409, "The run is on record but not live — its project was closed, or it ended before an app restart. There is no stream to open; read /result.")
            ]
        )
    }

    private static func runLogDetail() -> Detail {
        return Detail(
            id: "getRunLog",
            summary: "Read autopilot's log lines for this run",
            description: """
            What the Autopilot tab prints, for a caller with no tab: why a run ended the \
            way it did, where `events` says what the machine did. Autopilot keeps one \
            rolling project-wide log, so a run's share is the slice from its start until \
            the next run in the same project began. `truncated` is true when `limit` cut \
            the slice or the rolling buffer had already evicted its earlier lines.
            """,
            query: [QueryParameter(name: "limit", required: false, schema: boundedInteger(min: 1, max: 50),
                                   description: "Most recent lines to return, 1…50. Defaults to the whole slice.")],
            responses: [
                Status(code: 200, description: "The run's log slice.", schema: ref("RunLog")),
                errorStatus(400, "\"limit\" isn't an integer in 1…50."),
                errorStatus(404, "No run with this id, live or on record."),
                errorStatus(409, "The run is on record but not live — the rolling log buffer holds only the current process's lines.")
            ]
        )
    }

