    ], required: ["project"], anyOfRequired: [["item"], ["itemId"]]) }

    /// The table's only capture today is a run id; a new one without an entry here
    /// still gets a parameter, just a generic description.
    private static let pathParameterDescriptions = [
        "id": "The run id — the workflow execution id returned by POST /v1/runs."
    ]

    private static func projectQuery(required: Bool) -> QueryParameter {
        QueryParameter(
            name: "project", required: required, schema: string,
            description: required
                ? "Project identifier — canonical path, raw path or folder name."
                : "Narrow to one project. Without it the answer spans every project."
        )
    }

    private static func historyLimitQuery(default value: Int) -> QueryParameter {
        QueryParameter(name: "limit", required: false, schema: boundedInteger(min: 1, max: 200),
                       description: "How many records to return, 1…200. Defaults to \(value).")
    }

    // MARK: - Response schemas

    private static var schemas: [String: Any] { [
        "Error": object(["error": string], required: ["error"],
                        description: "Every error body the API returns."),

        "Health": object([
            "status": described(enumOf(["ok", "degraded"]),
                                "\"degraded\" when mainThreadLatencyMs is at or above the app's hitch threshold (200ms); \"ok\" below it."),
            "version": described(string, "The app's CFBundleShortVersionString — \"dev\" in unbundled builds."),
            "apiVersion": described(boundedInteger(min: 1), "The control API's version, raised whenever an endpoint the phone calls is added or changes shape."),
            "uptimeSeconds": described(boundedInteger(min: 0), "Whole seconds since the app launched."),
            "projectsOpen": boundedInteger(min: 0),
            "activeRuns": described(boundedInteger(min: 0), "Tracked runs reading running or awaiting_approval."),
            "mainThreadLatencyMs": described(number, "The latest main-thread latency probe, in milliseconds — what status is derived from."),
            "hitchCount": described(boundedInteger(min: 0), "Main-thread hitches recorded since launch, capped at the monitor's retained window."),
            "processMemoryMB": described(nullable(number), "Resident memory, in MB; null when the kernel refused the reading."),
            "activeSubprocessCount": described(boundedInteger(min: 0), "Live Claude Code subprocesses."),
            "holds": described(array(of: ref("SchedulerHold")),
                               "Projects whose autonomous starts are being withheld by their own failed runs. Empty is the healthy state."),
            "tools": described(array(of: ref("ProjectTools")),
                               "Per open project, the executables its verify commands run and where each resolved on the app's search path.")
        ], required: ["status", "version", "apiVersion", "uptimeSeconds", "projectsOpen", "activeRuns",
                     "mainThreadLatencyMs", "hitchCount", "processMemoryMB", "activeSubprocessCount", "holds", "tools"]),

        "ProjectTools": object([
            "project": string,
            "path": string,
            "tools": described(array(of: ref("Tool")), "One row per distinct executable, sorted by name."),
            "exports": described(array(of: ref("BuildExport")),
                                 "The variables every verify shell and agent spawn on this project's behalf runs with beyond PATH — derived from the tree (a Cargo.toml shares one cargo target directory across item worktrees) and the project's buildEnvironment map. Sorted by name.")
        ], required: ["project", "path", "tools", "exports"]),

        "BuildExport": object([
            "name": described(string, "The variable, as the child's environment spells it."),
            "value": described(string, "Its value, with ~ and $PROJECT_ROOT already expanded.")
        ], required: ["name", "value"]),

        "Tool": object([
            "name": described(string, "The executable as the verify command spells it."),
            "path": described(nullable(string), "Where it resolved; null when nothing on the search path is runnable by that name."),
            "searched": described(array(of: string), "The directories searched, present only when path is null.")
        ], required: ["name", "path"]),

        "SchedulerHold": object([
            "project": string,
            "path": string,
            "reason": described(string, "What the failures were and what would end the hold."),
            "failures": described(boundedInteger(min: 0), "Failed autonomous runs still standing as evidence."),
            "items": described(boundedInteger(min: 0), "Distinct items among them."),
            "systemic": described(bool, "Two different items failing the same way. An ordinary hold ends when the project's queue changes; a systemic one waits on the autopilot config, the global config, an app relaunch or resetBreaker.")
        ], required: ["project", "path", "reason", "failures", "items", "systemic"]),

        "Project": object([
            "id": described(string, "Canonical project path — the key everything else resolves to."),
            "name": described(string, "The project folder's name."),
            "path": string,
            "autopilotReady": described(bool, "True only when both a worker and a reviewer are assigned."),
            "gate": described(nullable(object([
                "item": described(string, "The item whose merge gate is verifying the merged tree right now."),
                "since": described(string, "ISO 8601 — when that verify began."),
                "state": described(enumOf(["verifying"]), "Always verifying: a gate that has answered is on the item, not here.")
            ], required: ["item", "since", "state"])), "The merge gate in progress for this project, whoever asked for it — a run's own or an approval's — or null."),
            "baseBranch": described(nullable(string), "The branch this project's runs fork from and land on: its configured `baseBranch`, or — when that is unset — the branch the checkout is on right now. null when the root is not a git repository or its HEAD is detached."),
            "unattendedPermissions": described(string, "How an unattended run is permitted: `auto` — its worker and reviewer run in Claude Code's auto mode, whose classifier decides each tool call, and anything that would prompt is refused; the worktree, the gate and a person are the boundaries."),
            "paused": described(bool, """
                The queue is held — either a human parked the project on the \
                fleet board or its own autopilot is paused (`POST \
                /v1/autopilot/pause`). `POST /v1/runs` answers 409 for a paused \
                project; `POST /v1/autopilot/resume` lifts it either way.
                """),
            "run": ref("AutopilotRunState"),
            "queue": ref("QueueDepth")
        ], required: ["id", "name", "path", "autopilotReady", "baseBranch", "unattendedPermissions", "paused", "run", "queue"]),

        "QueueDepth": object([
            "ready": described(boundedInteger(min: 0), "Items at `ready`, groomed or not."),
            "runnable": described(boundedInteger(min: 0), """
                Of those, the ones the Definition-of-Ready gate would actually let \
                autopilot pick up — the same verdict GET /v1/backlog reports as \
                `ready: true` per item. Zero with a non-zero `ready` means the \
                queue is full of ungroomed work.
                """),
            "draft": described(boundedInteger(min: 0), "Items at `draft` — filed, not yet triaged."),
            "active": described(boundedInteger(min: 0), "Items at `active` — in flight."),
            "inReview": described(boundedInteger(min: 0), "Items at `in-review` — the reviewer is judging them."),
            "awaitingApproval": described(boundedInteger(min: 0), "Items parked at the human gate."),
            "refusedAtGate": described(boundedInteger(min: 0), """
                Of `awaitingApproval`, the items whose merge gate already ran and \
                refused — the per-item `gate.state` of `refused`. Waiting on a fix, \
                not on a decision; subtract it to count what a person is actually \
                being asked.
                """),
            "blocked": described(boundedInteger(min: 0), "Items at `blocked` — stuck, waiting on triage.")
        ], required: ["ready", "runnable", "draft", "active", "inReview", "awaitingApproval", "refusedAtGate", "blocked"],
        description: """
            How much work the project has left, by status. Always present and \
            always complete: a project with no backlog, or one the parser could \
            make nothing of, reports zeros rather than omitting the block.
            """),

        "ProjectList": object(["projects": array(of: ref("Project"))], required: ["projects"]),

        "OpenedProject": object([
            "id": string,
            "name": string,
            "autopilotReady": bool,
            "alreadyOpen": described(bool, "True when the project was open already; the same value as `reloaded`."),
            "reloaded": described(bool, "True when the session was re-read from disk rather than created.")
        ], required: ["id", "name", "autopilotReady", "alreadyOpen", "reloaded"]),

        "ProjectAnswer": object([
            "project": described(string, "The project actually read, as the app names it — never the string that was asked for, which may have been a path."),
            "answer": described(string, """
                What the Planner found, having read the project's source. Already \
                carries the capped notice in its own text when `capped` is true, so a \
                caller that prints only this field still learns the answer was cut.
                """),
            "capped": described(bool, """
                True when the answer was cut at the bound. Always present: a capped \
                answer that didn't say so would read exactly like a complete one.
                """),
            "costUSD": described(number, """
                What the read cost, charged to the portfolio's daily ceiling — the same \
                pool grooming draws on. Materially higher than the free reads, which is \
                why this endpoint is asked for by name.
                """)
        ], required: ["project", "answer", "capped", "costUSD"],
        description: "One read of a named project's source."),

        "HiredAgent": object([
            "agentId": string,
            "name": string,
            "model": described(string, "The model actually used — the default when the request omitted one.")
        ], required: ["agentId", "name", "model"]),

        "BacklogItem": object([
            "id": string,
            "title": string,
            "epic": described(string, "The name of the section the item sits in."),
            "status": described(string, "e.g. draft, ready, active, awaiting-approval, done, blocked."),
            "size": described(nullable(string), "Declared size (S/M/L/XL); null when the item is unsized."),
            "lane": described(enumOf(BacklogLane.allCases.map(\.rawValue)), "now when the line is marked lane:now, later otherwise. Every now item runs before every later one."),
            "gate": described(nullable(object([
                "state": described(enumOf(["verifying", "waiting", "refused"]), "What the approval gate is doing for this item: verifying the merged tree, waiting on a person, or refused."),
                "since": described(nullable(string), "ISO 8601 — when the verify began, or when the refusal was recorded."),
                "reason": described(nullable(string), "The refusal, verbatim from the merge record; absent otherwise.")
            ], required: ["state"])), "Present only for an item at awaiting-approval: the gate as a step rather than a status that arrived early. A gate still verifying is not yet waiting on anyone."),
            "freshness": described(ref("BranchFreshness"), """
                Whether this item's branch still merges cleanly onto the project's \
                current base, checked with `git merge-tree` rather than by \
                attempting the merge. Present only for an item at \
                `awaiting-approval` that has actually been checked — a live-tree \
                project, or a gate item that predates this build, has nothing \
                cached yet.
                """)
        ], required: ["id", "title", "epic", "status", "size", "lane"]),

        "BranchFreshness": object([
            "clean": described(bool, "True when the branch still merges onto the current base with no conflict."),
            "conflicts": described(array(of: string), "The paths git could not merge cleanly. Empty when clean."),
            "checkedAt": described(dateTime, """
                When this verdict was computed — when the item reached the gate, \
                or after the most recent sibling merge, whichever is later.
                """)
        ], required: ["clean", "conflicts", "checkedAt"]),

        "BacklogParseIssue": object([
            "line": described(boundedInteger(min: 1), "1-based line number in BACKLOG.md."),
            "text": described(string, "The offending line, trimmed, as written."),
            "reason": described(string, "What went wrong, phrased for whoever is editing the file.")
        ], required: ["line", "text", "reason"],
        description: "A line of the backlog file the parser could not read as work. The line "
                   + "survives in the file; it is simply not an item as far as the app is concerned."),

        "StrandedItem": object([
            "id": string,
            "branch": described(string, "The ref the work is on — kiteloop/<id>."),
            "commitsAhead": described(integer, """
                Commits the branch carries that HEAD cannot reach. 0 for a worktree \
                finding (worktreePath present) — that finding is about uncommitted \
                files, not commits.
                """),
            "ledgerSays": described(string, "What the backlog claims, in the disagreement rule's own words."),
            "gitSays": described(string, "What git answered just now."),
            "worktreePath": described(string, """
                Present only for a worktree still on disk with uncommitted changes for \
                an item nothing is coming back for — the directory to go look at.
                """),
            "uncommittedFiles": described(integer, "Present alongside worktreePath: files uncommitted there.")
        ], required: ["id", "branch", "commitsAhead", "ledgerSays", "gitSays"],
        description: "An item marked done whose work never left its branch, or a worktree still on "
                   + "disk holding uncommitted changes nothing is coming back for."),

        "StrandedWork": object([
            "count": described(integer, """
                How many findings — done items stranded on an unmerged branch, plus \
                worktrees dirty for an item nothing is coming back for. 0 on a clean sweep.
                """),
            "unreadable": described(bool, """
                True when git could not be asked at all — no repository, or the listing \
                failed. Always present, so "asked, and nothing is stranded" cannot be read \
                off a response that means "could not ask"; `count` is 0 either way.
                """),
            "reason": described(string, "Present only when `unreadable` — why nothing could be read."),
            "doneItemsConsidered": described(integer, "How many done items the sweep was given."),
            "branchesExamined": described(integer, "How many of them cost a second git call."),
            "branchesNotExamined": described(integer, """
                Candidates left unasked because the branch budget ran out. Omitted when \
                the sweep finished, so a truncated sweep cannot read like a complete one.
                """),
            "items": described(array(of: ref("StrandedItem")),
                               "The stranded items themselves — empty on a clean sweep.")
        ], required: ["count", "unreadable", "doneItemsConsidered", "branchesExamined", "items"],
        description: "Done items whose work is still on an unmerged branch, plus worktrees dirty "
                   + "for an item nothing is coming back for. Nothing is merged, committed, deleted "
                   + "or pruned as a result — each finding is exactly the decision a person makes."),

        "BacklogList": object([
            "project": described(string, "The project folder's name."),
            "items": array(of: ref("BacklogItem")),
            "issues": described(array(of: ref("BacklogParseIssue")), """
                The lines the parser rejected, so a short item list can be told from a \
                short backlog. Always present — empty on a file that parsed cleanly.
                """),
            "strandedWork": ref("StrandedWork")
        ], required: ["project", "items", "issues", "strandedWork"]),

        "RunTimeoutSource": object([
            "worker": described(enumOf(["derived", "default"]), "Where stallTimeoutMinutes came from: \"derived\" once five of this project's runs carry a worker-phase duration, \"default\" until then."),
            "gate": described(enumOf(["derived", "default"]), "Where autoMergeVerifyTimeoutMinutes came from: \"derived\" once five of this project's runs carry a verify duration — the pre-review verify's or the merge gate's — \"default\" until then.")
        ], required: ["worker", "gate"],
        description: "Where each of the two derived clocks came from. One answer per clock, "
                   + "because each is counted from the runs that measured the phases it bounds: "
                   + "the worker's from worker phases, the gate's from either verify it holds to "
                   + "the one deadline, the larger of the two where a run measured both."),

        "AutopilotConfig": object([
            "project": described(string, "The project folder's name."),
            "worker": nullable(string),
            "reviewer": described(nullable(string), "Reviewer agent id; null when the project has no separate reviewer, as a project with no autopilot config yet does."),
            "autonomy": described(enumOf(["off", "propose", "land"]), "How far this project may go on its own — one dial for autonomousWorkEnabled and approvalGate below."),
            "approvalGate": described(enumOf(["propose", "land"]), "What happens to a run the reviewer passed: propose waits for a person, land approves and merges it."),
            "maxRetries": described(integer, "How many worker/reviewer rounds one item gets in a single run; a reviewer still sending the work back past the last one fails the run rather than looping."),
            "stallTimeoutMinutes": described(integer, "Read-only. How long a worker/reviewer node may make no progress before the run watchdog ends the item: this project's p95 worker-phase duration plus half again, floored at 15 minutes and capped at 60, or 20 until five of its runs carry a worker-phase duration. See runTimeoutSource.worker."),
            "budgetUSD": described(nullable(number), "This project's one budget — a daily ceiling that also bounds a sitting; null means it has none of its own and the portfolio's governs it alone. Replaces perItemCostCapUSD, sessionCostCapUSD, costCapMargin and dailyBudgetUSD."),
            "autoMergeOnApproval": described(bool, "Deprecated — read off approvalGate: true only at land. GET still reports it for one release."),
            "autoMergeVerifyTimeoutMinutes": described(integer, "Read-only. How long the merge gate's verify may run — the item's own verify: and the verify-map rules share the one clock — before a step still running is killed and the merge refused: this project's p95 verify duration — the pre-review verify's and the merge gate's, the larger per run — plus half again, floored at 10 minutes and uncapped, or 30 until five of its runs carry one. See runTimeoutSource.gate."), "runTimeoutSource": ref("RunTimeoutSource"), "workerMaxTurns": described(integer, "Read-only. How many turns the worker may take on one item — its node's maxTurns and its session's --max-turns: this project's p95 worker turn count plus half again, floored at 50 and capped at 150, or 50 until five of its runs carry a turn count. See workerMaxTurnsSource."), "workerMaxTurnsSource": described(enumOf(["derived", "default"]), "Where workerMaxTurns came from: \"derived\" once five of this project's runs carry a worker turn count, \"default\" until then."), "itemCostCapUSD": described(nullable(number), "Read-only. The per-item cost ceiling this project's runs imply: their p95 cost plus half again, never below an item's own predicted cost. null until five of its runs carry a cost; each item is then capped at its predicted cost plus half again, and uncapped when nothing predicts it. See itemCostCapSource."), "itemCostCapSource": described(enumOf(["derived", "default"]), "Where itemCostCapUSD came from: \"derived\" once five of this project's runs carry a cost, \"default\" until then."), "worktreeSetupCommand": described(nullable(string), "The command run in every worktree Kiteloop creates for this project — the worker's, the merge gate's scratch tree, the rebase scratch tree — right after checkout and before anything else runs there. null means nothing runs beyond what always has (today's behaviour)."),
            "effectiveAutoMergeVerifyCommand": described(nullable(string), "What the merge gate actually runs beside the item's verify: a merge-verify command stored by an earlier release while the verify map has no rule matching every path, else the verify map's widest rule; null when neither says anything."),
            "autoMergeVerifyCommandSource": described(string, "Where the effective merge-verify came from: \"configured\" for a command an earlier release stored, or the verify-map rule it was read from, or why there is none."),
            "effectiveWorktreeSetupCommand": described(nullable(string), "What a fresh worktree actually runs first: worktreeSetupCommand when set, else what the tree's lockfiles and generators imply; null when nothing."),
            "worktreeSetupCommandSource": described(string, "Where the effective setup came from: \"configured\", or the lockfiles and generators it was read from, or why there is none."),
            "baseBranch": described(nullable(string), "The local branch runs fork from and land on, as configured; null means the checkout's own HEAD. GET /v1/projects reports the branch that resolves to."),
            "openPullRequest": described(bool, "Whether a run reaching the approval gate has its branch pushed, a pull request opened for it, and that pull request's checks followed until they are green."),
            "approveReviewPassedRuns": described(bool, "Deprecated — read off approvalGate: true only at land. GET still reports it for one release. Whether a run the reviewer passed clears its approval gate itself rather than waiting for a person. Off by default; every automatic approval is recorded as one."),
            "autonomousWorkEnabled": described(bool, "Deprecated — folded into autonomy, which GET reports beside it. Whether the project has consented to unattended work. Off by default; only with it on do the fleet scheduler and the grooming loop pick the project up on their own.")
        ], required: ["project", "worker", "reviewer", "autonomy", "approvalGate", "maxRetries", "stallTimeoutMinutes",
                      "budgetUSD",
                      "autoMergeOnApproval", "autoMergeVerifyTimeoutMinutes",
                      "runTimeoutSource", "workerMaxTurns", "workerMaxTurnsSource", "itemCostCapUSD", "itemCostCapSource",
                      "worktreeSetupCommand", "effectiveAutoMergeVerifyCommand", "autoMergeVerifyCommandSource",
                      "effectiveWorktreeSetupCommand", "worktreeSetupCommandSource", "baseBranch",
                      "openPullRequest", "approveReviewPassedRuns", "autonomousWorkEnabled"],
        description: "The shape GET, PUT and reset all return, so a read always matches the last write. "
                   + "No coordinator field: the per-project persona picker retired, and a PUT tolerates "
                   + "one without any reply ever carrying it."),

        "AutopilotRunState": object([
            "state": described(enumOf(["idle", "running", "held", "inconsistent"]), """
                What the project is doing. `running`: an item is in flight. `idle`: nothing is. \
                `held`: a paused queue with items left, which resume picks up. `inconsistent`: \
                the autopilot's status claims a run with none behind it — a stale claim. This read \
                reports it and then clears it, so the next read, a run request and the fleet's next \
                look all find the slot free; reopening the project clears it too.
                """),
            "running": described(bool, "True exactly when `state` is `running` — and exactly "
                                     + "when POST /v1/runs would refuse with 409."),
            "item": described(nullable(string), "The item in flight; null unless running."),
            "itemTitle": nullable(string),
            "runId": described(nullable(string), "The execution driving it. Null while running "
                                               + "if the workflow has not spun up yet."),
            "startedAt": described(nullable(dateTime), "When the item became the one in flight."),
            "status": described(string, "What the autopilot's own status reads (idle, running, "
                                      + "reviewing, paused) — the claim `state` was checked against."),
            "heldItems": described(boundedInteger(min: 0), "Items still queued from the current one "
                                                        + "on, it included. For `held`, what a resume picks up."),
            "detail": described(nullable(string), "Why, for `held` and `inconsistent`; null otherwise."),
            "phaseRail": described(nullable(object([
                "currentStep": described(enumOf(["worker", "verify", "review", "merge", "gate"]),
                                          "Where in the pipeline this run is right now."),
                "stepsDone": described(array(of: enumOf(["worker", "verify", "review", "merge", "gate"])),
                                        "Every step before `currentStep`, in pipeline order."),
                "attempt": described(boundedInteger(min: 1), "The worker/reviewer round the current step belongs to."),
                "lastOutputAgeSeconds": described(number, "Seconds since the run last did anything "
                                                        + "recordable — the same clock the stall watchdog "
                                                        + "compares against its own timeout."),
                "warnAtSeconds": described(number, "Half the project's stallTimeoutMinutes, in seconds — "
                                                 + "past this, lastOutputAgeSeconds is a warning, ahead "
                                                 + "of the watchdog actually firing.")
            ], required: ["currentStep", "stepsDone", "attempt", "lastOutputAgeSeconds", "warnAtSeconds"])),
                "Null while running/reviewing has not logged its first phase yet, and always null "
              + "for `held` and `idle`.")
        ], required: ["state", "running", "item", "itemTitle", "runId", "startedAt",
                      "status", "heldItems", "detail", "phaseRail"],
        description: "What a project's autopilot is running, derived from the same check the "
                   + "run guard makes so the two always agree."),

        "AutopilotStatus": ["allOf": [
            ref("AutopilotConfig"),
            object([
                "run": ref("AutopilotRunState"),
                "sessionSpendUSD": described(number, "What the session has spent so far — every run "
                                                   + "since the app started or since a resume opened a "
                                                   + "new session, the item in flight included. This is "
                                                   + "the figure budgetUSD is measured against."),
                "paused": described(bool, "Whether this project's queue is held — by the fleet "
                                        + "board's paused switch or by POST /v1/autopilot/pause. The "
                                        + "same reading GET /v1/projects gives, and it stays true "
                                        + "after the item that was in flight when the pause arrived "
                                        + "finishes: only a resume lifts it.")
            ], required: ["run", "sessionSpendUSD", "paused"])
        ], "description": "What GET /v1/autopilot returns: the configuration plus live run state."],

        "AutopilotPaused": object(["project": string, "autopilot": const("paused")],
                                  required: ["project", "autopilot"]),

        "AutopilotResuming": object([
            "project": string,
            "autopilot": const("resuming"),
            "resumed": described(enumOf(["autopilot", "both"]),
                                  "Which hold this call lifted — the autopilot's own pause, "
                                  + "or that and the project's paused switch together.")
        ], required: ["project", "autopilot", "resumed"]),

        "AutopilotResumedProject": object([
            "project": string,
            "autopilot": const("idle"),
            "resumed": const("paused")
        ], required: ["project", "autopilot", "resumed"]),

        "FleetProject": object([
            "id": string,
            "name": string,
            "status": described(string, "What the autopilot's own status reads."),
            "state": described(enumOf(["idle", "running", "held", "inconsistent"]),
                               "The derived phase, read from the same check the run guard makes."),
            "running": bool,
            "item": described(nullable(string), "The item in flight; null unless running."),
            "heldItems": boundedInteger(min: 0),
            "heldByQuiesce": described(bool, "Whether POST /v1/fleet/resume will pick this one up. "
                                           + "False for a project that was already paused."),
            "action": described(nullable(enumOf(["held", "alreadyHeld", "idle"])),
                                "What the quiesce did to it — on that call's reply only, null on a "
                              + "plain reading. `idle` means there was no queue to hold: the gate "
                              + "is what stops an idle project taking new work.")
        ], required: ["id", "name", "status", "state", "running", "item", "heldItems",
                      "heldByQuiesce", "action"]),

        "FleetReading": object([
            "quiesced": described(bool, "New work is being refused fleet-wide."),
            "drained": described(bool, "No run in flight anywhere. A restart strands nothing when "
                                     + "this and `quiesced` are both true."),
            "running": described(boundedInteger(min: 0), "Projects with a run still finishing."),
            "summary": described(string, "The same reading as one line."),
            "projects": array(of: ref("FleetProject"))
        ], required: ["quiesced", "drained", "running", "summary", "projects"],
        description: "Where the fleet is — the answer that replaces polling GET /v1/projects."),

        "FleetResumed": ["allOf": [
            ref("FleetReading"),
            object([
                "resumed": described(array(of: string), "Projects whose queue was picked back up."),
                "skipped": described(array(of: object(["project": string, "reason": string],
                                                      required: ["project", "reason"])),
                                     "Ledgered projects that could not be resumed, and why — after "
                                   + "a restart, all of them.")
            ], required: ["resumed", "skipped"])
        ], "description": "What POST /v1/fleet/resume returns: the reading after the hold was lifted, plus what it did."],

        "RefillSettings": object([
            "enabled": bool,
            "dailyBudgetUSD": described(nullable(number), "null means no ceiling."),
            "maxPasses": described(nullable(integer), "The day's other ceiling, in passes rather than dollars; null means no ceiling. Persisted as `coordinatorMaxPassesPerDay`, so it survives a restart."),
            "checkIntervalSeconds": described(integer, "How often the loop looks. Not persisted — a restart is back to 900."),
            "policy": ref("RefillPolicy")
        ], required: ["enabled", "dailyBudgetUSD", "maxPasses", "checkIntervalSeconds", "policy"],
        description: "What PUT /v1/coordinator/refill answers — the settings only. GET answers RefillStatus."),

        "RefillPolicy": object([
            "threshold": described(integer, "Ready-queue depth below which a project gets a refill."),
            "targetDepth": described(integer, "The depth a refill tops a queue back up to."),
            "maxItemsPerPass": described(integer, "The most items one pass drafts for one project. It defaults to targetDepth: a cap below the target made the target unreachable, so an emptied queue needed two passes to reach a depth the policy had set itself."),
            "maxProjectsPerPass": described(integer, "The most projects one pass serves. A pass used to top up exactly one, so the cadence divided by the fleet size and a project that drained faster than its turn sat at zero.")
        ], required: ["threshold", "targetDepth", "maxItemsPerPass", "maxProjectsPerPass"],
        description: "Reported **sanitized** — the policy a pass actually applies, not the one that was sent."),

        "RefillPass": object([
            "at": dateTime,
            "outcome": described(string, "The tag to switch on: disabled, held, noDrafts, filed, triaged or abandoned."),
            "detail": described(string, "The same line the log and Activity feed carry."),
            "project": nullable(string),
            "hold": described(string, "Present only on a hold: which gate held."),
            "reason": described(string, "Present only on a hold."),
            "stage": described(string, "Present only on an abandoned pass: triaging, drafting, gating or filing — where it was stuck."),
            "ranForSeconds": described(integer, "Present only on an abandoned pass: how long it ran before it was ended."),
            "abandonedBecause": described(string, "Present only on an abandoned pass: deadline, or switchedOff."),
            "ready": described(integer, "Present only on a filed pass."),
            "drafts": described(integer, "Present only on a filed pass."),
            "retry": described(integer, "Present only on a triaged pass."),
            "regroom": described(integer, "Present only on a triaged pass."),
            "escalate": described(integer, "Present only on a triaged pass.")
        ], required: ["at", "outcome", "detail", "project"],
        description: "The count fields are present only for the outcome that has them, so a filed pass is never confused with a held one reporting zeroes."),

        "RefillStatus": object([
            "enabled": bool,
            "passInFlight": bool,
            "passInFlightSince": described(nullable(dateTime), "When the pass in flight started; null when none is. Read with passDeadlineSeconds, this is what says a loop has stopped rather than merely being between passes."),
            "passStage": described(nullable(string), "What the pass in flight is doing — triaging, drafting, gating or filing. Null when none is."),
            "passStalled": described(bool, "Whether a pass has been in flight past its deadline, or the last one had to be ended at it. The flag alone read true for 2h22m once, beside ceilings that were all healthy."),
            "passDeadlineSeconds": described(integer, "How long a pass may run before it is ended and the next one let through."),
            "checkIntervalSeconds": integer,
            "policy": ref("RefillPolicy"),
            "budget": object([
                "spentUSD": number,
                "capUSD": nullable(number),
                "passesUsed": integer,
                "maxPasses": nullable(integer),
                "abandonedPasses": described(integer, "How many of today's passes were ended rather than finished. Counted beside passesUsed, never inside it, and always present including as 0 — passStalled only ever answers \"right now\", so a night that hung repeatedly and self-healed each time read exactly like one that never hung."),
                "day": described(string, "The local calendar day these counters describe, as \"YYYY-MM-DD\" — they zero at local midnight, so the date has to agree with that boundary rather than name a UTC instant."),
                "exhausted": bool,
                "exhaustionReason": described(nullable(string), "null while there's budget left.")
            ], required: ["spentUSD", "capUSD", "passesUsed", "maxPasses", "abandonedPasses",
                          "day", "exhausted", "exhaustionReason"]),
            "historyLimit": described(integer, "How many passes are kept in memory at most."),
            "count": described(integer, "Passes in this response."),
            "passes": array(of: ref("RefillPass"))
        ], required: ["enabled", "passInFlight", "passInFlightSince", "passStage",
                      "passStalled", "passDeadlineSeconds", "checkIntervalSeconds", "policy",
                      "budget", "historyLimit", "count", "passes"]),

        "SchedulerStart": object([
            "at": dateTime,
            "project": string,
            "item": string,
            "title": string,
            "why": described(string, "Why this project and item were chosen."),
            "budget": described(string, "The day's budget as it stood at the start, e.g. \"$3.20 of $20.00\"."),
            "outcome": described(string, "running until the run ends, then done, awaiting-approval, blocked, cancelled — or did-not-run, or interrupted for a start read back from the log whose process died mid-run."),
            "finishedAt": nullable(dateTime)
        ], required: ["at", "project", "item", "title", "why", "budget", "outcome", "finishedAt"]),

        "SchedulingStatus": object([
            "enabled": bool,
            "checkIntervalSeconds": integer,
            "startInFlight": bool,
            "startsInFlight": described(integer, "How many autonomous runs are executing right now, across projects."),
            "maxConcurrentRuns": described(integer, "How many the fleet may have in flight at once, 1…8; each project still runs one at a time. Persisted."),
            "breaker": described(object([
                "open": described(bool, "Whether any project is being withheld."),
                "reason": described(nullable(string), "Every active hold's reason, joined; null when nothing is held."),
                "holds": array(of: ref("SchedulerHold"))
            ], required: ["open", "reason", "holds"]),
            "Autonomous holds, one per project. Keyed \"breaker\" because resetBreaker is still what clears them; it is no longer a fleet-wide latch, and a hold ends on its own when the queue it was about changes."),
            "budget": object([
                "budgetUSD": nullable(number),
                "spentTodayUSD": number,
                "remainingUSD": nullable(number),
                "exhausted": bool
            ], required: ["budgetUSD", "spentTodayUSD", "remainingUSD", "exhausted"]),
            "lastDecision": nullable(object(["kind": string, "detail": string], required: ["kind", "detail"])),
            "historyLimit": described(integer, "How many starts are kept in memory at most."),
            "count": described(integer, "Starts in this response."),
            "starts": array(of: ref("SchedulerStart"))
        ], required: ["enabled", "checkIntervalSeconds", "startInFlight", "startsInFlight", "maxConcurrentRuns", "breaker", "budget",
                      "lastDecision", "historyLimit", "count", "starts"]),

        "TemplateVariable": object([
            "name": string,
            "description": nullable(string),
            "required": described(bool, "A stamp that omits a required variable is refused."),
            "pattern": described(nullable(string), "A regular expression the value must match whole. Null accepts any single-line value.")
        ], required: ["name", "required"]),

        "Template": object([
            "name": described(string, "The file's stem — what POST .../stamp takes as \"template\"."),
            "path": described(string, "Where it was read from."),
            "description": nullable(string),
            "epic": described(nullable(string), "The epic stamped items are filed under, when the backlog has one by that name."),
            "items": described(integer, "How many items it stamps."),
            "variables": array(of: ref("TemplateVariable")),
            "error": described(string, "Why this file could not be read as a template. Present only on a template that doesn't parse, in which case the fields above it are absent.")
        ], required: ["name", "path"]),

        "TemplateList": object([
            "directories": described(array(of: string), "Where the app looked, nearest first — so an empty list is readable."),
            "templates": array(of: ref("Template"))
        ], required: ["directories", "templates"]),

        "StampedItem": object([
            "id": string,
            "title": string,
            "status": described(string, "What it would be filed as: ready, or draft when a gate refused it."),
            "size": string,
            "verify": string,
            "needs": described(array(of: string), "The stamped items this one waits for — the template's ordering."),
            "gates": described(array(of: string), "Why it isn't ready, in the gates' own words. Empty when it is."),
            "detail": described(string, "The backlog/<id>.md this would write, as markdown.")
        ], required: ["id", "title", "status", "size", "verify", "needs", "gates", "detail"]),

        "TemplateStamp": object([
            "template": string,
            "epic": described(string, "The backlog section the items go under."),
            "applied": described(bool, "False on a preview — nothing was written."),
            "items": array(of: ref("StampedItem")),
            "filed": described(array(of: string), "The ids written. Present only when applied.")
        ], required: ["template", "epic", "applied", "items"]),

        "Metric": object([
            "runId": described(nullable(string), "The workflow execution id, so a run can be followed from its events into its metrics. Null on records written before the id was recorded."),
            "item": string,
            "title": string,
            "project": described(string, "The project folder's name."),
            "epic": nullable(string),
            "size": described(nullable(string), "Declared size at execution time."),
            "startedAt": dateTime,
            "completedAt": dateTime,
            "durationSec": integer,
            "costUSD": number,
            "predictedCostUSD": described(nullable(number), "What the item was forecast to cost, at pickup — the number its cap was set from. Null when there was nothing to predict from; never 0, which would read as a forecast of free."),
            "overItemCap": described(nullable(bool), "Whether the run crossed that per-item ceiling. The cap is advisory, so true means the overrun was recorded and the item finished. Null is unknown — a record written before this was captured — which is not the same as false."),
            "reviewerRetries": described(integer, "Rework loops — reviewer passes beyond the first."),
            "outcome": string,
            "worker": nullable(string),
            "reviewer": nullable(string),
            "qualityScore": described(nullable(number), "Advisory LLM-judge score, 0–1."),
            "judgeDimensions": described(["type": ["object", "null"], "additionalProperties": number],
                                         "Per-dimension judge scores, e.g. verify_passed, scope_respected."),
            "judgeUnavailable": described(nullable(string), "Why there's no score. Distinguishes a judge that died from work that scored badly."),
            "qualityScoreDiffTruncated": described(nullable(bool), "Whether the diff the judge scored was cut short before it reached the judge. Null when the judge was never asked; true/false otherwise, so a truncated score can be filtered out of an average rather than blended in with the ones taken over the whole diff.")
        ], required: ["runId", "item", "title", "project", "epic", "size", "startedAt", "completedAt",
                      "durationSec", "costUSD", "predictedCostUSD", "overItemCap", "reviewerRetries",
                      "outcome", "worker", "reviewer",
                      "qualityScore", "judgeDimensions", "judgeUnavailable", "qualityScoreDiffTruncated"]),

        "EscapedDefectRate": object([
            "windowDays": integer,
            "approvals": described(integer, "The denominator: approvals observed."),
            "reopened": described(integer, "The numerator: approvals followed by a reopen inside the window."),
            "lateReopened": described(integer, "Reopens outside the window, so a 0% rate can be told from \"everything came back on day 30\"."),
            "rate": described(nullable(number), "null until something has been approved — 0/0 is \"not measured yet\", not a perfect 0%.")
        ], required: ["windowDays", "approvals", "reopened", "lateReopened", "rate"]),

        "FirstPassRate": object([
            "judged": described(integer, "The denominator: runs that reached a verdict — done, awaiting-approval or blocked. A cancelled run is in neither half."),
            "firstPass": described(integer, "The numerator: of those, the ones review passed with no rework loop behind them."),
            "rate": described(nullable(number), "null until a run has been judged — 0/0 is \"not measured yet\", not \"nothing passes\".")
        ], required: ["judged", "firstPass", "rate"]),

        "MetricList": object([
            "count": described(integer, "Records in this response."),
            "metrics": array(of: ref("Metric")),
            "escapedDefects": described(ref("EscapedDefectRate"), "Whole-history, not limited to the records above."),
            "firstPassRate": described(ref("FirstPassRate"), "Whole-history, not limited to the records above."),
            "project": described(string, "Present only when the request narrowed to one project.")
        ], required: ["count", "metrics", "escapedDefects", "firstPassRate"]),

        "Estimate": object([
            "item": string,
            "project": described(string, "The project folder's name."),
            "createdAt": dateTime,
            "size": described(string, "Estimated size."),
            "predictedDurationSec": integer,
            "predictedCostUSD": described(nullable(number), "null when history was too thin to ground a cost — an unknown, not a free run."),
            "predictedRetries": nullable(integer),
            "confidence": described(number, "0–1, higher with more historical samples."),
            "source": described(string, "How the estimate was produced, e.g. \"hybrid\"."),
            "rationale": string
        ], required: ["item", "project", "createdAt", "size", "predictedDurationSec", "predictedCostUSD",
                      "predictedRetries", "confidence", "source", "rationale"]),

        "EstimateList": object([
            "count": described(integer, "Estimates in this response."),
            "estimates": array(of: ref("Estimate")),
            "project": described(string, "Present only when the request narrowed to one project.")
        ], required: ["count", "estimates"]),

        "GroomingRecord": object([
            "at": dateTime,
            "item": described(string, "The backlog item the record is about."),
            "project": described(string, "The project folder's name."),
            "event": described(enumOf(["filed-ready", "filed-draft", "check-failed"]),
                               "A filing, split by the stage it landed at — or a pre-run check's refusal."),
            "check": described(nullable(string),
                               "Which check refused it — definition-of-ready, grounding-check or retry-ceiling. null for a filing."),
            "reason": described(nullable(string), "The failing clause, as the verdict phrased it. null for a filing.")
        ], required: ["at", "item", "project", "event", "check", "reason"]),

        "GroomingList": object([
            "count": described(integer, "Records in this response."),
            "grooming": array(of: ref("GroomingRecord")),
            "project": described(string, "Present only when the request narrowed to one project.")
        ], required: ["count", "grooming"]),

        "MemoryProposal": object([
            "id": string,
            "agent": described(string, "The agent id the proposal is filed against."),
            "status": described(const("pending"), "Always \"pending\" — an approved or rejected proposal is not reported here."),
            "source": described(enumOf(["agent", "librarian"]), "An agent's own propose_memory call, or a consolidation pass over the corpus."),
            "operation": described(enumOf(["add", "merge", "delete", "archive"]), "What approving this would do to the index."),
            "topics": described(array(of: string), "The fact names \"merge\", \"delete\" and \"archive\" act on. Omitted for \"add\", which acts on none."),
            "content": described(string, "The proposed fact text. For \"delete\" and \"archive\" this is the reason, not new content."),
            "rationale": described(nullable(string), "Why this is being proposed, in the proposer's own words."),
            "evidence": described(nullable(string), "What contradicts the fact a \"delete\" removes. null for every other operation."),
            "timestamp": dateTime
        ], required: ["id", "agent", "status", "source", "operation", "content", "rationale", "evidence", "timestamp"]),

        "MemoryProposalList": object([
            "project": described(string, "The project folder's name."),
            "count": described(integer, "Proposals in this response."),
            "proposals": array(of: ref("MemoryProposal"))
        ], required: ["project", "count", "proposals"]),

        "MemoryProposalAnswer": object([
            "project": described(string, "The project folder's name."),
            "id": described(string, "The proposal that was answered."),
            "agent": described(string, "The agent id it was filed against."),
            "operation": described(string, "What it did to the index: \"add\", \"merge\", \"delete\" or \"archive\". Reported for a rejection too, as what was turned down."),
            "status": described(string, "\"approved\" or \"rejected\" — the status the proposal now carries.")
        ], required: ["project", "id", "agent", "operation", "status"]),

        "ReportPeriod": object([
            "hours": described(boundedInteger(min: 1, max: 720), "The window asked for."),
            "label": described(string, "How the window reads in a header, e.g. \"last 24h\"."),
            "start": dateTime,
            "end": dateTime
        ], required: ["hours", "label", "start", "end"]),

        "MergeRate": object([
            "merged": integer,
            "of": described(integer, "The denominator — see basis."),
            "basis": described(enumOf(["filed", "run"]), """
                What the rate is measured against. filed is the rate that judges the \
                grooming; run is the fallback for a period in which nothing was filed, \
                and answers a different question ("did what ran land?").
                """),
            "fraction": described(nullable(number), "null when there is nothing to divide by — 0/0 is \"not measured\", not 0%.")
        ], required: ["merged", "of", "basis", "fraction"]),

        "RejectionCause": object([
            "label": described(string, "The check that refused the item, or \"no check verdict\" when none had."),
            "count": integer,
            "example": described(nullable(string), "One verdict verbatim, so there is something to go and fix.")
        ], required: ["label", "count", "example"]),

        "PortfolioRow": object([
            "project": described(string, "The project folder's name — or \"All projects\" on the total."),
            "filed": described(integer, "Items filed in the period."),
            "ready": described(integer, "Of those, filed at ready."),
            "draft": described(integer, "Of those, filed at draft."),
            "run": described(integer, "Items that reached a terminal outcome in the period."),
            "merged": described(integer, "Items whose work landed on main."),
            "rejected": described(integer, "Items that ended blocked — review never passed, or the run was cut short."),
            "awaitingApproval": described(integer, "Passed review and parked for a human: neither merged nor rejected."),
            "skippedByCheck": described(integer, "Items a pre-run check refused at pickup, so they never ran."),
            "spendUSD": number,
            "idleSeconds": described(integer, "Period time with no item running."),
            "quiet": described(bool, "Nothing was filed, nothing ran, nothing was refused."),
            "mergeRate": ref("MergeRate"),
            "causes": described(array(of: ref("RejectionCause")), "Most common first, at most three."),
            "text": described(string, "The row as the app renders it, e.g. \"filed 5 (4 ready · 1 draft) · run 4 · merged 3 · $3.90 · idle 19h\".")
        ], required: ["project", "filed", "ready", "draft", "run", "merged", "rejected",
                      "awaitingApproval", "skippedByCheck", "spendUSD", "idleSeconds", "quiet",
                      "mergeRate", "causes", "text"]),

        "PortfolioReport": object([
            "period": ref("ReportPeriod"),
            "summary": described(string, "The one line a collapsed panel shows."),
            "empty": described(bool, "Nothing was groomed and nothing ran anywhere."),
            "rows": described(array(of: ref("PortfolioRow")), "Per project, busiest first, at most six."),
            "total": described(ref("PortfolioRow"), "Every project in the period, including any rows left out."),
            "omittedProjects": described(integer, "Projects folded into the total but not listed in rows.")
        ], required: ["period", "summary", "empty", "rows", "total", "omittedProjects"]),

        "RunStarted": object([
            "runId": described(string, "The workflow execution id — the runId every other run endpoint takes. Absent when status is \"starting\": the run was accepted but had not named itself before the response went out, and inventing an id would name a transcript that doesn't exist."),
            "item": string,
            "title": string,
            "status": described(enumOf(["running", "starting"]),
                                "\"starting\" means accepted and spinning up, not refused — read run.runId from GET /v1/autopilot, or post the item again (while it is in flight that answers 409 naming the run rather than starting it twice)."),
            "detail": described(string, "Where to find the id. Present only when status is \"starting\".")
        ], required: ["item", "title", "status"]),

        "RunSummary": object(withRunCost([
            "runId": string,
            "executionId": described(string, "The workflow execution this run turned out to be — what its transcript directory and its metric record are keyed by. Equal to runId for a run started through POST /v1/runs; for a scheduler-opened auto-… run it is the only way to join the two. Absent while it isn't yet known, and on a run that never got an execution."),
            "item": string,
            "title": string,
            "project": described(string, "The project folder's name."),
            "startedAt": dateTime,
            "state": described(enumOf(["running", "awaiting_approval", "finished", "interrupted", "unknown"]),
                               "unknown means the run's project has since been closed and nothing is driving it; interrupted means an app restart ended it."),
            "historical": described(bool, "True for a record read back from ~/.kiteloop/control-runs.jsonl rather than a run this process is tracking."),
            "endedAt": described(dateTime, "When the run reached its ending — the wall clock the run closed at, which `durationSec` is not: that measures the item rather than the run. Reported as soon as the run has ended, whether it finished in this process or in an earlier one. Absent while a run is still working, and on an interrupted one, which reached no ending to report."),
            "outcome": described(enumOf(["done", "awaiting_approval", "investigation", "blocked", "cancelled", "did_not_run"]),
                                 "Present on any run that reached an ending, whether it finished in this process or in an earlier one. Absent while a run is still working, and on an interrupted one. did_not_run is a start a pickup gate refused: it spent nothing and reached no ending of its own, which is why it is not blocked."),
            "reason": described(string, "Why the run ended as it did — what tells one blocked run from another. Present when the run's record kept one; absent while it is still working."),
            "durationSec": described(integer, "How long the run took. Absent while a run is still working, and on one nothing measured to an end."),
            "qualityScore": described(number, "Present on a run that has ended and whose judge returned a score."),
            "judgeDimensions": described(["type": "object", "additionalProperties": number],
                                         "Present only alongside a qualityScore."),
            "judgeUnavailable": described(string, "Present instead of a score when the judge didn't deliver one.")
        ]), required: ["runId", "item", "title", "project", "startedAt", "state", "historical"]),

        "RunList": object(["runs": array(of: ref("RunSummary"))], required: ["runs"]),

        "RunEvent": object([
            "ts": dateTime,
            "type": string,
            "source": string
        ], required: ["ts", "type", "source"]),

        "RunStatus": object([
            "runId": string,
            "executionId": described(string, "The workflow execution this run turned out to be — see RunSummary. Absent while it isn't yet known, and on a run that never got an execution."),
            "item": string,
            "title": string,
            "startedAt": described(dateTime, "When the run was started — the same value GET /v1/runs reports for it."),
            "endedAt": described(dateTime, "When the run reached its ending — the wall clock the run closed at, which `durationSec` is not: that measures the item rather than the run. Reported as soon as the run has ended, whether it finished in this process or in an earlier one. Absent while a run is still working, and on an interrupted one, which reached no ending to report."),
            "autopilot": described(enumOf(["idle", "running", "reviewing", "paused"]),
                                   "The project's autopilot, not this run. Absent on a historical run whose project is closed."),
            "itemStatus": described(string, "The backlog item's status, or \"unknown\" if it's gone from the file."),
            "events": described(array(of: ref("RunEvent")), "This run's last 20 events. Always empty on a historical run — bus history isn't durable."),
            "historical": described(bool, "True when answered from the durable record rather than from anything live."),
            "state": described(enumOf(["running", "awaiting_approval", "finished", "interrupted", "unknown"]),
                               "Present only on a historical run; a live one is described by autopilot/executionStatus."),
            "outcome": described(enumOf(["done", "awaiting_approval", "investigation", "blocked", "cancelled", "did_not_run"]),
                                 "Present only on a historical run that reached an ending. did_not_run is a start a pickup gate refused: it spent nothing and reached no ending of its own, which is why it is not blocked."),
            "currentNode": described(string, "Present while the workflow execution exists."),
            "executionStatus": described(string, "Present while the workflow execution exists."),
            "approvalQuestion": described(string, "Present only while a workflow approval node is waiting.")
        ], required: ["runId", "item", "title", "startedAt", "itemStatus", "events", "historical"]),

        "RunResult": object(withRunCost([
            "runId": string,
            "executionId": described(string, "The workflow execution this run turned out to be — see RunSummary. Absent while it isn't yet known, and on a run that never got an execution."),
            "item": string,
            "title": string,
            "startedAt": described(dateTime, "When the run was started — what durationSec is measured from, and the only thing that places the run in time."),
            "endedAt": described(dateTime, "When the run reached its ending — the wall clock the run closed at, which `durationSec` is not: that measures the item rather than the run. Reported as soon as the run has ended, whether it finished in this process or in an earlier one. Absent while a run is still working, and on an interrupted one, which reached no ending to report."),
            "state": described(enumOf(["finished", "interrupted", "unknown"]),
                               "interrupted: an app restart ended the run before it reached an outcome. unknown: it was still open when its project was closed."),
            "outcome": described(enumOf(["done", "awaiting_approval", "investigation", "blocked", "cancelled", "did_not_run"]),
                                 "Absent when the run never reached an ending — see state. did_not_run is a start a pickup gate refused: it spent nothing and reached no ending of its own, which is why it is not blocked."),
            "durationSec": described(integer, "Absent on a run nothing measured to an end."),
            "itemStatus": string,
            "historical": described(bool, "True when answered from the durable record rather than from a run this process finished."),
            "reason": described(string, "Why the run ended as it did. Present when the outcome is blocked, and on a did_not_run start, where it carries the pickup gate's own words."),
            "branch": described(string, "Present when the run's work landed on a branch."),
            "pullRequestUrl": described(string, "Present when openPullRequest is on and a pull request was opened for the branch. Absent when it was skipped — the item's Notes say why."),
            "approval": described(enumOf(["automatic"]), "Present only when the run cleared the item's approval gate itself (approveReviewPassedRuns). Absent otherwise, including for an item a person approved — that happens after this record closes."),
            "merged": described(bool, "Present only when the run attempted its own merge (autonomy land, or autoMergeOnApproval with approveReviewPassedRuns): true when the branch landed, false when the gate refused it — the item's Notes and GET /v1/backlog's strandedWork say why. Absent when this run attempted none, which is not the same as unmerged: a merge a person triggers at the gate happens after this record closes."),
            "mergeCommit": described(string, "The commit the branch became on the base. Present only alongside merged: true."),
            "qualityScore": described(number, "Present only when the judge returned a score."),
            "judgeDimensions": described(["type": "object", "additionalProperties": number],
                                         "Present only alongside a qualityScore."),
            "judgeUnavailable": described(string, "Present instead of a score when the judge didn't deliver one."),
            "verifyExitStatus": described(integer, "What the item's own verify: answered when the app ran it before the reviewer: 0 and only 0 is a pass, and a negative status is a command that never returned one — read verifyTimedOut to tell which. Kept on the run's durable record, so a historical readout reports it too. Absent, never null, when no verdict was taken — or when the record predates these fields — which is not the same as a verify that passed."),
            "verifyCommand": described(string, "The verify: command as it was run. Present only alongside a verifyExitStatus, on a live reading and a historical one alike."),
            "verifyOutputTail": described(string, "The last 40 lines the verify: printed. Present only alongside a verifyExitStatus, on a live reading and a historical one alike."),
            "verifyTimedOut": described(bool, "True when the deadline is what ended the command, rather than the command answering — the one thing that tells a negative verifyExitStatus that ran out of clock from one that could not be spawned. A killed command judged nothing about the tree. Present alongside a verifyExitStatus on a live reading; on a historical one, absent when the run's durable record predates this field."),
            "verifyDirectory": described(string, "The directory the verify: ran in — the run's worktree, or the project root for a live-tree run, which is what says a verify passed in the wrong tree. Present alongside a verifyExitStatus on a live reading; on a historical one, absent when the run's durable record predates this field.")
        ]), required: ["runId", "item", "title", "startedAt", "state", "itemStatus", "historical"]),

        "RunPending": object(withRunCost([
            "runId": string,
            "executionId": described(string, "The workflow execution this run turned out to be — see RunSummary. Absent while it isn't yet known, and on a run that never got an execution."),
            "item": string,
            "title": string,
            "startedAt": described(dateTime, "When the run was started — how long a poll loop has been waiting on it."),
            "state": enumOf(["running", "awaiting_approval"]),
            "itemStatus": string,
            "historical": described(bool, "Always false — a 202 is only ever a live run."),
            "approvalQuestion": described(string, "Present only while a workflow approval node is waiting.")
        ]), required: ["runId", "item", "title", "startedAt", "state", "itemStatus", "historical"]),

        "RunLogLine": object(["ts": dateTime, "message": string], required: ["ts", "message"]),

        "RunLog": object([
            "runId": string,
            "item": string,
            "title": string,
            "project": described(string, "The project folder's name."),
            "count": described(integer, "Lines in this response."),
            "truncated": described(bool, "True when `limit` cut the slice, or the rolling buffer had already evicted the run's earlier lines."),
            "lines": array(of: ref("RunLogLine"))
        ], required: ["runId", "item", "title", "project", "count", "truncated", "lines"]),

