        ], required: ["runId", "gate", "resolved"],
        description: "Answered when a mid-workflow human-approval node was the gate holding the run."),

        "ItemGateResolution": object([
            "item": string,
            "runId": described(string, "Present only when the gate was resolved through POST /v1/runs/{runId}/approve."),
            "resolved": enumOf(["approved", "rejected"]),
            "status": described(string, "The item's status afterwards: done on approval, ready on rejection.")
        ], required: ["item", "resolved", "status"]),

        "ItemLanding": object([
