                "state": described(string, "idle, working or waitingForHuman.")
            ], required: ["id", "name", "state"]))
        ], required: ["agents"]),
        "AgentMessage": object([
            "agent": described(string, "The agent's id."),
            "reply": described(string, "With wait: the agent's answer; absent when queued."),
            "queued": described(bool, "True when the agent was mid-turn and the message waits its turn."),
            "started": described(bool, "Without wait: true when the agent was idle and the turn has begun."),
            "after": described(string, "Without wait: the chat's last message id before this one, for GET /v1/agents/events.")
        ], required: ["agent", "queued"]),
        "AgentTranscript": object([
            "agent": described(string, "The agent's id."),
            "messages": array(of: object([
                "id": string,
                "sender": described(string, "you, the agent's name, or system."),
                "kind": described(string, "text, thinking, tool, error, system, plan or question."),
                "text": string,
                "at": described(string, "ISO-8601."),
                "path": described(string, "On a file tool's tool message: the whole path it touched."),
                "plan": described(object(["open": bool, "answer": string], required: ["open"]),
                                  "On a plan: whether it waits, and the answer once chosen."),
                "question": described(object(["request": string, "open": bool], required: ["request", "open"]),
                                      "On a question: the request id to answer it with, and whether it waits.")
            ], required: ["id", "sender", "kind", "text", "at"]))
        ], required: ["agent", "messages"]),
        "ItemDetail": object([
            "id": string,
            "title": string,
            "status": string,
            "epic": string,
            "size": string,
            "verify": described(string, "The verify commands, one per line."),
            "what": string,
            "approach": string,
            "acceptanceCriteria": array(of: string),
            "outOfScope": array(of: string),
            "notes": string,
            "why": string
        ], required: ["id", "title", "status"]),
        "ItemDiff": object([
            "item": string,
            "branch": described(string, "The autopilot branch the diff reads from."),
            "stat": described(string, "git diff --stat, one line per file plus the summary."),
            "patch": described(string, "The unified diff, capped at 200000 characters."),
            "truncated": described(bool, "True when the patch hit the cap.")
        ], required: ["item", "branch", "stat", "patch", "truncated"]),
        "ItemRelease": object([
            "item": string,
            "released": described(string, "When the release took effect (ISO-8601). Attempts that finished at or before it stop counting."),
            "wasRetired": described(bool, "Whether the ceiling was actually refusing the item. False means the release was a no-op."),
            "noWorkAttemptsBefore": described(integer, "The count the release cleared."),
            "noWorkAttempts": described(integer, "What the next pickup will read — 0 immediately after a release."),
            "ceiling": described(integer, "Attempts allowed before the item is retired again.")
        ], required: ["item", "released", "wasRetired", "noWorkAttemptsBefore", "noWorkAttempts", "ceiling"]),
        "ItemRefresh": object([
            "item": string,
            "result": enumOf(["refreshed", "failed", "retired"]),
            "detail": described(string, "What happened — the failure reason on \"failed\", or why the item is retired.")
        ], required: ["item", "result"])
    ] }

    // MARK: - JSON Schema helpers

    private static var string: [String: Any] { ["type": "string"] }
    private static var bool: [String: Any] { ["type": "boolean"] }
    private static var number: [String: Any] { ["type": "number"] }
    private static var integer: [String: Any] { ["type": "integer"] }
    private static var dateTime: [String: Any] { ["type": "string", "format": "date-time"] }

    /// Advisory mode's retired vocabulary — kept only to describe the
    /// deprecated, ignored `mode` field on PUT /v1/coordinator/refill.
    private static var coordinatorMode: [String: Any] { enumOf(["advisory", "bounded"]) }

    private static func boundedInteger(min: Int, max: Int? = nil) -> [String: Any] {
        var schema: [String: Any] = ["type": "integer", "minimum": min]
        if let max { schema["maximum"] = max }
        return schema
    }

    private static func nullable(_ schema: [String: Any]) -> [String: Any] {
        var nullable = schema
        // 3.1 is JSON Schema 2020-12: a nullable type is a type union, not a flag.
        if let type = schema["type"] as? String { nullable["type"] = [type, "null"] }
        return nullable
    }

    private static func array(of items: [String: Any]) -> [String: Any] {
        ["type": "array", "items": items]
    }

    private static func enumOf(_ values: [String]) -> [String: Any] {
        ["type": "string", "enum": values]
    }

    private static func const(_ value: String) -> [String: Any] {
        ["type": "string", "const": value]
    }

    /// Adds the three cost fields every run payload carries — what the run has
    /// spent, the ceiling it is measured against, and where that ceiling's
    /// forecast came from. Shared rather than repeated per schema: a driver
    /// pacing itself off the listing and then reading the bill off the result has
    /// to be reading the same three fields under the same names.
    ///
    /// None of them is ever required. Each is **absent rather than zero** when it
    /// can't be established — a run whose spend nothing could be attributed to
    /// did not cost $0, and the two read very differently to whoever is deciding
    /// whether tonight's queue is affordable.
    private static func withRunCost(_ properties: [String: Any]) -> [String: Any] {
        properties.merging([
            "costUSD": described(number, """
                What this run has spent so far, and its final cost once it has \
                finished. Absent when no spend could be attributed to it.
                """),
            "costCapUSD": described(number, """
                The effective per-item ceiling this run is measured against — \
                this project's p95 run cost plus half again, never below the \
                item's predicted cost (itemCostCapUSD). Absent \
                when the run is uncapped, or when it was never observed while in \
                flight.
                """),
            "predictionSource": described(string, """
                Which rung of the prediction chain produced the forecast behind \
                costCapUSD: "own history", "stored estimate" or "size band p50". \
                Absent when nothing was predicted and the flat cap is the whole \
                story.
                """)
        ]) { declared, _ in declared }
    }

    private static func described(_ schema: [String: Any], _ description: String) -> [String: Any] {
        var described = schema
        described["description"] = description
        return described
    }

    private static func ref(_ name: String) -> [String: Any] {
        ["$ref": "#/components/schemas/\(name)"]
    }

    /// `anyOfRequired` is how "one of these keys, either spelling" is stated —
    /// several bodies take `item` or its `itemId` alias, and a schema that
    /// demanded one spelling would reject requests the handler accepts.
    private static func object(_ properties: [String: Any],
                               required: [String],
                               anyOfRequired: [[String]] = [],
                               description: String? = nil) -> [String: Any] {
        var schema: [String: Any] = ["type": "object", "properties": properties]
        if !required.isEmpty { schema["required"] = required }
        if !anyOfRequired.isEmpty { schema["anyOf"] = anyOfRequired.map { ["required": $0] } }
        if let description { schema["description"] = description }
        return schema
    }

    private static func errorStatus(_ code: Int, _ description: String) -> Status {
        Status(code: code, description: description, schema: ref("Error"))
    }

    private static func errorResponse(_ description: String) -> [String: Any] {
        ["description": description, "content": ["application/json": ["schema": ref("Error")]]]
    }
}
